// Minimal JSON value + strict parser producing nlohmann-compatible diagnostics.
#pragma once
#include <cstdint>
#include <map>
#include <memory>
#include <stdexcept>
#include <string>
#include <vector>

namespace jt {

struct JsonValue;
using JsonPtr = std::shared_ptr<JsonValue>;

enum class JsonType { Null, Boolean, Integer, Unsigned, Float, String, Array, Object };

struct JsonValue {
  JsonType type = JsonType::Null;
  bool boolean = false;
  int64_t integer = 0;
  uint64_t unsigned_integer = 0;
  double number = 0.0;
  std::string string;
  std::vector<JsonPtr> array;
  // Objects keep their keys sorted (std::map semantics).
  std::vector<std::pair<std::string, JsonPtr>> object;

  bool IsContainer() const { return type == JsonType::Array || type == JsonType::Object; }
  bool IsObject() const { return type == JsonType::Object; }
  bool IsArray() const { return type == JsonType::Array; }
  bool IsString() const { return type == JsonType::String; }
  bool IsNumber() const {
    return type == JsonType::Integer || type == JsonType::Unsigned || type == JsonType::Float;
  }
  size_t Size() const { return type == JsonType::Array ? array.size() : object.size(); }
  const JsonValue* Find(const std::string& key) const;
};

class JsonError : public std::runtime_error {
 public:
  explicit JsonError(const std::string& what) : std::runtime_error(what) {}
};

// Parse a complete JSON document from a byte buffer. Throws JsonError.
JsonPtr ParseJson(const std::string& input);

// Serialize a number exactly like the reference implementation does.
std::string DumpNumber(const JsonValue& value);
std::string DumpDouble(double value);

}  // namespace jt
