#include <algorithm>
#include <array>
#include <cerrno>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>

namespace jt {

const JsonValue* JsonValue::Find(const std::string& key) const {
  for (const auto& kv : object) {
    if (kv.first == key) return kv.second.get();
  }
  return nullptr;
}

namespace {

// ---------------------------------------------------------------------------
// Lexer
// ---------------------------------------------------------------------------
enum class Token {
  Uninitialized,
  LiteralTrue,
  LiteralFalse,
  LiteralNull,
  ValueString,
  ValueUnsigned,
  ValueInteger,
  ValueFloat,
  BeginArray,
  BeginObject,
  EndArray,
  EndObject,
  NameSeparator,
  ValueSeparator,
  ParseError,
  EndOfInput,
  LiteralOrValue,
};

const char* TokenName(Token t) {
  switch (t) {
    case Token::Uninitialized: return "<uninitialized>";
    case Token::LiteralTrue: return "true literal";
    case Token::LiteralFalse: return "false literal";
    case Token::LiteralNull: return "null literal";
    case Token::ValueString: return "string literal";
    case Token::ValueUnsigned:
    case Token::ValueInteger:
    case Token::ValueFloat: return "number literal";
    case Token::BeginArray: return "'['";
    case Token::BeginObject: return "'{'";
    case Token::EndArray: return "']'";
    case Token::EndObject: return "'}'";
    case Token::NameSeparator: return "':'";
    case Token::ValueSeparator: return "','";
    case Token::ParseError: return "<parse error>";
    case Token::EndOfInput: return "end of input";
    case Token::LiteralOrValue: return "'[', '{', or a literal";
  }
  return "unknown token";
}

constexpr int kEof = -1;

class Lexer {
 public:
  explicit Lexer(const std::string& input) : input_(input) {}

  Token Scan() {
    if (chars_read_total_ == 0 && !SkipBom()) {
      error_message_ = "invalid BOM; must be 0xEF 0xBB 0xBF if given";
      return Token::ParseError;
    }
    // skip whitespace
    do {
      Get();
    } while (current_ == ' ' || current_ == '\t' || current_ == '\n' || current_ == '\r');

    switch (current_) {
      case '[': return Token::BeginArray;
      case ']': return Token::EndArray;
      case '{': return Token::BeginObject;
      case '}': return Token::EndObject;
      case ':': return Token::NameSeparator;
      case ',': return Token::ValueSeparator;
      case 't': return ScanLiteral("true", Token::LiteralTrue);
      case 'f': return ScanLiteral("false", Token::LiteralFalse);
      case 'n': return ScanLiteral("null", Token::LiteralNull);
      case '"': return ScanString();
      case '-':
      case '0':
      case '1':
      case '2':
      case '3':
      case '4':
      case '5':
      case '6':
      case '7':
      case '8':
      case '9': return ScanNumber();
      case 0:
      case kEof: return Token::EndOfInput;
      default:
        error_message_ = "invalid literal";
        return Token::ParseError;
    }
  }

  std::string Position() const {
    return "at line " + std::to_string(lines_read_ + 1) + ", column " +
           std::to_string(chars_read_current_line_);
  }

  std::string TokenString() const {
    std::string result;
    for (unsigned char c : token_string_) {
      if (c <= 0x1F) {
        char buf[16];
        std::snprintf(buf, sizeof(buf), "<U+%.4X>", c);
        result += buf;
      } else {
        result.push_back(static_cast<char>(c));
      }
    }
    return result;
  }

  const std::string& ErrorMessage() const { return error_message_; }
  const std::string& StringValue() const { return token_buffer_; }
  uint64_t UnsignedValue() const { return value_unsigned_; }
  int64_t IntegerValue() const { return value_integer_; }
  double FloatValue() const { return value_float_; }
  size_t CharsReadTotal() const { return chars_read_total_; }

 private:
  int Get() {
    ++chars_read_total_;
    ++chars_read_current_line_;
    if (next_unget_) {
      next_unget_ = false;
    } else {
      if (pos_ < input_.size()) {
        current_ = static_cast<unsigned char>(input_[pos_++]);
      } else {
        current_ = kEof;
      }
    }
    if (current_ != kEof) token_string_.push_back(static_cast<char>(current_));
    if (current_ == '\n') {
      ++lines_read_;
      chars_read_current_line_ = 0;
    }
    return current_;
  }

  void Unget() {
    next_unget_ = true;
    --chars_read_total_;
    if (chars_read_current_line_ == 0) {
      if (lines_read_ > 0) --lines_read_;
    } else {
      --chars_read_current_line_;
    }
    if (current_ != kEof && !token_string_.empty()) token_string_.pop_back();
  }

  void Add(int c) { token_buffer_.push_back(static_cast<char>(c)); }

  void Reset() {
    token_buffer_.clear();
    token_string_.clear();
    token_string_.push_back(static_cast<char>(current_));
  }

  bool SkipBom() {
    if (Get() == 0xEF) {
      return Get() == 0xBB && Get() == 0xBF;
    }
    Unget();
    return true;
  }

  Token ScanLiteral(const char* literal, Token result) {
    const size_t length = std::strlen(literal);
    for (size_t i = 1; i < length; ++i) {
      if (Get() != static_cast<unsigned char>(literal[i])) {
        error_message_ = "invalid literal";
        return Token::ParseError;
      }
    }
    return result;
  }

  int GetCodepoint() {
    int codepoint = 0;
    for (const int factor : {12, 8, 4, 0}) {
      Get();
      if (current_ >= '0' && current_ <= '9') {
        codepoint += (current_ - 0x30) << factor;
      } else if (current_ >= 'A' && current_ <= 'F') {
        codepoint += (current_ - 0x37) << factor;
      } else if (current_ >= 'a' && current_ <= 'f') {
        codepoint += (current_ - 0x57) << factor;
      } else {
        return -1;
      }
    }
    return codepoint;
  }

  bool NextByteInRange(std::initializer_list<int> ranges) {
    Add(current_);
    for (auto range = ranges.begin(); range != ranges.end(); ++range) {
      Get();
      const int lo = *range;
      const int hi = *(++range);
      if (lo <= current_ && current_ <= hi) {
        Add(current_);
      } else {
        error_message_ = "invalid string: ill-formed UTF-8 byte";
        return false;
      }
    }
    return true;
  }

  Token ScanString() {
    Reset();
    while (true) {
      switch (Get()) {
        case kEof:
          error_message_ = "invalid string: missing closing quote";
          return Token::ParseError;
        case '"': return Token::ValueString;
        case '\\': {
          switch (Get()) {
            case '"': Add('"'); break;
            case '\\': Add('\\'); break;
            case '/': Add('/'); break;
            case 'b': Add('\b'); break;
            case 'f': Add('\f'); break;
            case 'n': Add('\n'); break;
            case 'r': Add('\r'); break;
            case 't': Add('\t'); break;
            case 'u': {
              const int codepoint1 = GetCodepoint();
              int codepoint = codepoint1;
              if (codepoint1 == -1) {
                error_message_ = "invalid string: '\\u' must be followed by 4 hex digits";
                return Token::ParseError;
              }
              if (0xD800 <= codepoint1 && codepoint1 <= 0xDBFF) {
                if (Get() == '\\' && Get() == 'u') {
                  const int codepoint2 = GetCodepoint();
                  if (codepoint2 == -1) {
                    error_message_ = "invalid string: '\\u' must be followed by 4 hex digits";
                    return Token::ParseError;
                  }
                  if (0xDC00 <= codepoint2 && codepoint2 <= 0xDFFF) {
                    codepoint = (codepoint1 << 10) + codepoint2 - 0x35FDC00;
                  } else {
                    error_message_ =
                        "invalid string: surrogate U+D800..U+DBFF must be followed by U+DC00..U+DFFF";
                    return Token::ParseError;
                  }
                } else {
                  error_message_ =
                      "invalid string: surrogate U+D800..U+DBFF must be followed by U+DC00..U+DFFF";
                  return Token::ParseError;
                }
              } else {
                if (0xDC00 <= codepoint1 && codepoint1 <= 0xDFFF) {
                  error_message_ =
                      "invalid string: surrogate U+DC00..U+DFFF must follow U+D800..U+DBFF";
                  return Token::ParseError;
                }
              }
              if (codepoint < 0x80) {
                Add(codepoint);
              } else if (codepoint <= 0x7FF) {
                Add(0xC0 | (codepoint >> 6));
                Add(0x80 | (codepoint & 0x3F));
              } else if (codepoint <= 0xFFFF) {
                Add(0xE0 | (codepoint >> 12));
                Add(0x80 | ((codepoint >> 6) & 0x3F));
                Add(0x80 | (codepoint & 0x3F));
              } else {
                Add(0xF0 | (codepoint >> 18));
                Add(0x80 | ((codepoint >> 12) & 0x3F));
                Add(0x80 | ((codepoint >> 6) & 0x3F));
                Add(0x80 | (codepoint & 0x3F));
              }
              break;
            }
            default:
              error_message_ = "invalid string: forbidden character after backslash";
              return Token::ParseError;
          }
          break;
        }
        default: {
          const int c = current_;
          if (c >= 0x00 && c <= 0x1F) {
            static const char* const names[] = {
                "NUL", "SOH", "STX", "ETX", "EOT", "ENQ", "ACK", "BEL", "BS",  "HT",  "LF",
                "VT",  "FF",  "CR",  "SO",  "SI",  "DLE", "DC1", "DC2", "DC3", "DC4", "NAK",
                "SYN", "ETB", "CAN", "EM",  "SUB", "ESC", "FS",  "GS",  "RS",  "US"};
            char buf[128];
            std::snprintf(buf, sizeof(buf),
                          "invalid string: control character U+%04X (%s) must be escaped to \\u%04X",
                          c, names[c], c);
            error_message_ = buf;
            switch (c) {
              case 0x08: error_message_ += " or \\b"; break;
              case 0x09: error_message_ += " or \\t"; break;
              case 0x0A: error_message_ += " or \\n"; break;
              case 0x0C: error_message_ += " or \\f"; break;
              case 0x0D: error_message_ += " or \\r"; break;
              default: break;
            }
            return Token::ParseError;
          }
          if (c >= 0x20 && c <= 0x7F) {
            Add(c);
            break;
          }
          if (c >= 0xC2 && c <= 0xDF) {
            if (!NextByteInRange({0x80, 0xBF})) return Token::ParseError;
            break;
          }
          if (c == 0xE0) {
            if (!NextByteInRange({0xA0, 0xBF, 0x80, 0xBF})) return Token::ParseError;
            break;
          }
          if ((c >= 0xE1 && c <= 0xEC) || c == 0xEE || c == 0xEF) {
            if (!NextByteInRange({0x80, 0xBF, 0x80, 0xBF})) return Token::ParseError;
            break;
          }
          if (c == 0xED) {
            if (!NextByteInRange({0x80, 0x9F, 0x80, 0xBF})) return Token::ParseError;
            break;
          }
          if (c == 0xF0) {
            if (!NextByteInRange({0x90, 0xBF, 0x80, 0xBF, 0x80, 0xBF})) return Token::ParseError;
            break;
          }
          if (c >= 0xF1 && c <= 0xF3) {
            if (!NextByteInRange({0x80, 0xBF, 0x80, 0xBF, 0x80, 0xBF})) return Token::ParseError;
            break;
          }
          if (c == 0xF4) {
            if (!NextByteInRange({0x80, 0x8F, 0x80, 0xBF, 0x80, 0xBF})) return Token::ParseError;
            break;
          }
          error_message_ = "invalid string: ill-formed UTF-8 byte";
          return Token::ParseError;
        }
      }
    }
  }

  static bool IsDigit(int c) { return c >= '0' && c <= '9'; }

  Token ScanNumber() {
    Reset();
    Token number_type = Token::ValueUnsigned;
    enum State {
      kMinus, kZero, kAny1, kDecimal1, kDecimal2, kExponent, kSign, kAny2, kDone
    } state;

    switch (current_) {
      case '-':
        Add(current_);
        state = kMinus;
        break;
      case '0':
        Add(current_);
        state = kZero;
        break;
      default:
        Add(current_);
        state = kAny1;
        break;
    }

    while (state != kDone) {
      switch (state) {
        case kMinus:
          number_type = Token::ValueInteger;
          switch (Get()) {
            case '0': Add(current_); state = kZero; break;
            default:
              if (IsDigit(current_)) {
                Add(current_);
                state = kAny1;
              } else {
                error_message_ = "invalid number; expected digit after '-'";
                return Token::ParseError;
              }
          }
          break;
        case kZero:
          switch (Get()) {
            case '.': Add('.'); state = kDecimal1; break;
            case 'e':
            case 'E': Add(current_); state = kExponent; break;
            default: state = kDone;
          }
          break;
        case kAny1:
          Get();
          if (IsDigit(current_)) {
            Add(current_);
          } else if (current_ == '.') {
            Add('.');
            state = kDecimal1;
          } else if (current_ == 'e' || current_ == 'E') {
            Add(current_);
            state = kExponent;
          } else {
            state = kDone;
          }
          break;
        case kDecimal1:
          number_type = Token::ValueFloat;
          Get();
          if (IsDigit(current_)) {
            Add(current_);
            state = kDecimal2;
          } else {
            error_message_ = "invalid number; expected digit after '.'";
            return Token::ParseError;
          }
          break;
        case kDecimal2:
          Get();
          if (IsDigit(current_)) {
            Add(current_);
          } else if (current_ == 'e' || current_ == 'E') {
            Add(current_);
            state = kExponent;
          } else {
            state = kDone;
          }
          break;
        case kExponent:
          number_type = Token::ValueFloat;
          Get();
          if (current_ == '+' || current_ == '-') {
            Add(current_);
            state = kSign;
          } else if (IsDigit(current_)) {
            Add(current_);
            state = kAny2;
          } else {
            error_message_ = "invalid number; expected '+', '-', or digit after exponent";
            return Token::ParseError;
          }
          break;
        case kSign:
          Get();
          if (IsDigit(current_)) {
            Add(current_);
            state = kAny2;
          } else {
            error_message_ = "invalid number; expected digit after exponent sign";
            return Token::ParseError;
          }
          break;
        case kAny2:
          Get();
          if (IsDigit(current_)) {
            Add(current_);
          } else {
            state = kDone;
          }
          break;
        case kDone: break;
      }
    }

    // unget the character after the number
    Unget();

    char* endptr = nullptr;
    errno = 0;
    if (number_type == Token::ValueUnsigned) {
      const unsigned long long x = std::strtoull(token_buffer_.c_str(), &endptr, 10);
      if (errno == 0) {
        value_unsigned_ = static_cast<uint64_t>(x);
        if (value_unsigned_ == x) return Token::ValueUnsigned;
      }
    } else if (number_type == Token::ValueInteger) {
      const long long x = std::strtoll(token_buffer_.c_str(), &endptr, 10);
      if (errno == 0) {
        value_integer_ = static_cast<int64_t>(x);
        if (value_integer_ == x) return Token::ValueInteger;
      }
    }
    value_float_ = std::strtod(token_buffer_.c_str(), &endptr);
    return Token::ValueFloat;
  }

  const std::string& input_;
  size_t pos_ = 0;
  int current_ = 0;
  bool next_unget_ = false;
  size_t chars_read_total_ = 0;
  size_t chars_read_current_line_ = 0;
  size_t lines_read_ = 0;
  std::string token_string_;
  std::string token_buffer_;
  std::string error_message_;
  uint64_t value_unsigned_ = 0;
  int64_t value_integer_ = 0;
  double value_float_ = 0.0;
};

// ---------------------------------------------------------------------------
// Parser
// ---------------------------------------------------------------------------
class Parser {
 public:
  explicit Parser(const std::string& input) : lexer_(input) { GetToken(); }

  JsonPtr Parse() {
    JsonPtr result = ParseInternal();
    if (GetToken() != Token::EndOfInput) {
      ThrowParseError(ExceptionMessage(Token::EndOfInput, "value"));
    }
    return result;
  }

 private:
  Token GetToken() { return last_token_ = lexer_.Scan(); }

  [[noreturn]] void ThrowParseError(const std::string& what) {
    throw JsonError("[json.exception.parse_error.101] parse error " + lexer_.Position() + ": " + what);
  }

  std::string ExceptionMessage(Token expected, const std::string& context) {
    std::string msg = "syntax error ";
    if (!context.empty()) msg += "while parsing " + context + " ";
    msg += "- ";
    if (last_token_ == Token::ParseError) {
      msg += lexer_.ErrorMessage() + "; last read: '" + lexer_.TokenString() + "'";
    } else {
      msg += std::string("unexpected ") + TokenName(last_token_);
    }
    if (expected != Token::Uninitialized) {
      msg += std::string("; expected ") + TokenName(expected);
    }
    return msg;
  }

  struct Frame {
    JsonPtr container;
    std::string key;  // pending key for objects
  };

  void AddValue(std::vector<Frame>& stack, JsonPtr& root, JsonPtr value) {
    if (stack.empty()) {
      root = value;
      return;
    }
    Frame& top = stack.back();
    if (top.container->type == JsonType::Array) {
      top.container->array.push_back(value);
    } else {
      // std::map semantics: sorted keys, duplicate keys keep the first inserted value
      auto& obj = top.container->object;
      auto it = std::lower_bound(obj.begin(), obj.end(), top.key,
                                 [](const std::pair<std::string, JsonPtr>& a, const std::string& b) {
                                   return a.first < b;
                                 });
      if (it != obj.end() && it->first == top.key) {
        it->second = value;  // operator[] assignment overwrites the value
      } else {
        obj.insert(it, {top.key, value});
      }
    }
  }

  JsonPtr ParseInternal() {
    std::vector<Frame> states;
    JsonPtr root;
    bool skip_to_state_evaluation = false;

    while (true) {
      if (!skip_to_state_evaluation) {
        switch (last_token_) {
          case Token::BeginObject: {
            auto obj = std::make_shared<JsonValue>();
            obj->type = JsonType::Object;
            AddValue(states, root, obj);
            if (GetToken() == Token::EndObject) break;
            if (last_token_ != Token::ValueString) {
              ThrowParseError(ExceptionMessage(Token::ValueString, "object key"));
            }
            std::string key = lexer_.StringValue();
            if (GetToken() != Token::NameSeparator) {
              ThrowParseError(ExceptionMessage(Token::NameSeparator, "object separator"));
            }
            states.push_back({obj, key});
            GetToken();
            continue;
          }
          case Token::BeginArray: {
            auto arr = std::make_shared<JsonValue>();
            arr->type = JsonType::Array;
            AddValue(states, root, arr);
            if (GetToken() == Token::EndArray) break;
            states.push_back({arr, ""});
            continue;
          }
          case Token::ValueFloat: {
            const double res = lexer_.FloatValue();
            if (!std::isfinite(res)) {
              throw JsonError("[json.exception.out_of_range.406] number overflow parsing '" +
                              lexer_.TokenString() + "'");
            }
            auto v = std::make_shared<JsonValue>();
            v->type = JsonType::Float;
            v->number = res;
            AddValue(states, root, v);
            break;
          }
          case Token::LiteralFalse:
          case Token::LiteralTrue: {
            auto v = std::make_shared<JsonValue>();
            v->type = JsonType::Boolean;
            v->boolean = (last_token_ == Token::LiteralTrue);
            AddValue(states, root, v);
            break;
          }
          case Token::LiteralNull: {
            auto v = std::make_shared<JsonValue>();
            v->type = JsonType::Null;
            AddValue(states, root, v);
            break;
          }
          case Token::ValueInteger: {
            auto v = std::make_shared<JsonValue>();
            v->type = JsonType::Integer;
            v->integer = lexer_.IntegerValue();
            AddValue(states, root, v);
            break;
          }
          case Token::ValueUnsigned: {
            auto v = std::make_shared<JsonValue>();
            v->type = JsonType::Unsigned;
            v->unsigned_integer = lexer_.UnsignedValue();
            AddValue(states, root, v);
            break;
          }
          case Token::ValueString: {
            auto v = std::make_shared<JsonValue>();
            v->type = JsonType::String;
            v->string = lexer_.StringValue();
            AddValue(states, root, v);
            break;
          }
          case Token::ParseError:
            ThrowParseError(ExceptionMessage(Token::Uninitialized, "value"));
          case Token::EndOfInput:
            if (lexer_.CharsReadTotal() == 1) {
              ThrowParseError(
                  "attempting to parse an empty input; check that your input string or stream "
                  "contains the expected JSON");
            }
            ThrowParseError(ExceptionMessage(Token::LiteralOrValue, "value"));
          default:
            ThrowParseError(ExceptionMessage(Token::LiteralOrValue, "value"));
        }
      } else {
        skip_to_state_evaluation = false;
      }

      if (states.empty()) return root;

      if (states.back().container->type == JsonType::Array) {
        if (GetToken() == Token::ValueSeparator) {
          GetToken();
          continue;
        }
        if (last_token_ == Token::EndArray) {
          states.pop_back();
          skip_to_state_evaluation = true;
          continue;
        }
        ThrowParseError(ExceptionMessage(Token::EndArray, "array"));
      }

      // object
      if (GetToken() == Token::ValueSeparator) {
        if (GetToken() != Token::ValueString) {
          ThrowParseError(ExceptionMessage(Token::ValueString, "object key"));
        }
        states.back().key = lexer_.StringValue();
        if (GetToken() != Token::NameSeparator) {
          ThrowParseError(ExceptionMessage(Token::NameSeparator, "object separator"));
        }
        GetToken();
        continue;
      }
      if (last_token_ == Token::EndObject) {
        states.pop_back();
        skip_to_state_evaluation = true;
        continue;
      }
      ThrowParseError(ExceptionMessage(Token::EndObject, "object"));
    }
  }

  Lexer lexer_;
  Token last_token_ = Token::Uninitialized;
};

// ---------------------------------------------------------------------------
// Shortest round-trip double formatting (Grisu2 style, matching the reference
// implementation's output format).
// ---------------------------------------------------------------------------
struct DiyFp {
  uint64_t f;
  int e;
};

DiyFp DiyMul(DiyFp x, DiyFp y) {
  const uint64_t u_lo = x.f & 0xFFFFFFFFu;
  const uint64_t u_hi = x.f >> 32u;
  const uint64_t v_lo = y.f & 0xFFFFFFFFu;
  const uint64_t v_hi = y.f >> 32u;
  const uint64_t p0 = u_lo * v_lo;
  const uint64_t p1 = u_lo * v_hi;
  const uint64_t p2 = u_hi * v_lo;
  const uint64_t p3 = u_hi * v_hi;
  const uint64_t p0_hi = p0 >> 32u;
  const uint64_t p1_lo = p1 & 0xFFFFFFFFu;
  const uint64_t p1_hi = p1 >> 32u;
  const uint64_t p2_lo = p2 & 0xFFFFFFFFu;
  const uint64_t p2_hi = p2 >> 32u;
  uint64_t q = p0_hi + p1_lo + p2_lo;
  q += uint64_t{1} << (64u - 32u - 1u);  // round, ties up
  const uint64_t h = p3 + p2_hi + p1_hi + (q >> 32u);
  return {h, x.e + y.e + 64};
}

DiyFp DiyNormalize(DiyFp x) {
  while ((x.f >> 63u) == 0) {
    x.f <<= 1u;
    x.e--;
  }
  return x;
}

DiyFp DiyNormalizeTo(DiyFp x, int target_exponent) {
  const int delta = x.e - target_exponent;
  return {x.f << delta, target_exponent};
}

struct Boundaries {
  DiyFp w;
  DiyFp minus;
  DiyFp plus;
};

Boundaries ComputeBoundaries(double value) {
  constexpr int kPrecision = 53;
  constexpr int kBias = 1023 + (kPrecision - 1);
  constexpr int kMinExp = 1 - kBias;
  constexpr uint64_t kHiddenBit = uint64_t{1} << (kPrecision - 1);
  uint64_t bits;
  std::memcpy(&bits, &value, sizeof(bits));
  const uint64_t E = bits >> (kPrecision - 1);
  const uint64_t F = bits & (kHiddenBit - 1);
  const bool is_denormal = (E == 0);
  const DiyFp v = is_denormal ? DiyFp{F, kMinExp} : DiyFp{F + kHiddenBit, static_cast<int>(E) - kBias};
  const bool lower_boundary_is_closer = (F == 0 && E > 1);
  const DiyFp m_plus = DiyFp{2 * v.f + 1, v.e - 1};
  const DiyFp m_minus = lower_boundary_is_closer ? DiyFp{4 * v.f - 1, v.e - 2} : DiyFp{2 * v.f - 1, v.e - 1};
  const DiyFp w_plus = DiyNormalize(m_plus);
  const DiyFp w_minus = DiyNormalizeTo(m_minus, w_plus.e);
  return {DiyNormalize(v), w_minus, w_plus};
}

constexpr int kAlpha = -60;
constexpr int kGamma = -32;

struct CachedPower {
  uint64_t f;
  int e;
  int k;
};

// Simple arbitrary precision unsigned integer (base 2^32), enough to compute
// the cached powers of ten exactly.
struct BigUint {
  std::vector<uint32_t> limbs;  // little endian

  static BigUint FromU64(uint64_t v) {
    BigUint b;
    while (v) {
      b.limbs.push_back(static_cast<uint32_t>(v & 0xFFFFFFFFu));
      v >>= 32u;
    }
    return b;
  }
  bool IsZero() const { return limbs.empty(); }
  void Trim() {
    while (!limbs.empty() && limbs.back() == 0) limbs.pop_back();
  }
  void MulSmall(uint32_t m) {
    uint64_t carry = 0;
    for (auto& limb : limbs) {
      const uint64_t p = static_cast<uint64_t>(limb) * m + carry;
      limb = static_cast<uint32_t>(p & 0xFFFFFFFFu);
      carry = p >> 32u;
    }
    if (carry) limbs.push_back(static_cast<uint32_t>(carry));
  }
  int BitLength() const {
    if (limbs.empty()) return 0;
    int bits = static_cast<int>(limbs.size() - 1) * 32;
    uint32_t top = limbs.back();
    while (top) {
      bits++;
      top >>= 1u;
    }
    return bits;
  }
  bool Bit(int i) const {
    if (i < 0) return false;
    const size_t limb = static_cast<size_t>(i) / 32;
    if (limb >= limbs.size()) return false;
    return (limbs[limb] >> (i % 32)) & 1u;
  }
  // Extract 64 bits starting at bit position `from` (bits from..from+63).
  uint64_t Extract64(int from) const {
    uint64_t result = 0;
    for (int i = 63; i >= 0; --i) {
      result = (result << 1u) | (Bit(from + i) ? 1u : 0u);
    }
    return result;
  }
  static BigUint Pow10(int k) {
    BigUint b = FromU64(1);
    for (int i = 0; i < k; ++i) b.MulSmall(10);
    return b;
  }
  static BigUint Pow2(int n) {
    BigUint b;
    b.limbs.assign(static_cast<size_t>(n / 32) + 1, 0);
    b.limbs[static_cast<size_t>(n / 32)] = 1u << (n % 32);
    return b;
  }
  // Compare
  int Compare(const BigUint& o) const {
    if (limbs.size() != o.limbs.size()) return limbs.size() < o.limbs.size() ? -1 : 1;
    for (size_t i = limbs.size(); i-- > 0;) {
      if (limbs[i] != o.limbs[i]) return limbs[i] < o.limbs[i] ? -1 : 1;
    }
    return 0;
  }
  // this -= o (requires this >= o)
  void Sub(const BigUint& o) {
    int64_t borrow = 0;
    for (size_t i = 0; i < limbs.size(); ++i) {
      int64_t v = static_cast<int64_t>(limbs[i]) - borrow - (i < o.limbs.size() ? o.limbs[i] : 0);
      if (v < 0) {
        v += (int64_t{1} << 32);
        borrow = 1;
      } else {
        borrow = 0;
      }
      limbs[i] = static_cast<uint32_t>(v);
    }
    Trim();
  }
  BigUint ShiftLeft(int n) const {
    BigUint r;
    const int limb_shift = n / 32;
    const int bit_shift = n % 32;
    r.limbs.assign(limbs.size() + static_cast<size_t>(limb_shift) + 1, 0);
    for (size_t i = 0; i < limbs.size(); ++i) {
      const uint64_t v = static_cast<uint64_t>(limbs[i]) << bit_shift;
      r.limbs[i + static_cast<size_t>(limb_shift)] |= static_cast<uint32_t>(v & 0xFFFFFFFFu);
      r.limbs[i + static_cast<size_t>(limb_shift) + 1] |= static_cast<uint32_t>(v >> 32u);
    }
    r.Trim();
    return r;
  }
  // Integer division by binary long division: returns floor(this / d).
  BigUint Div(const BigUint& d) const {
    BigUint quotient;
    BigUint remainder;
    const int bits = BitLength();
    quotient.limbs.assign(static_cast<size_t>(bits / 32) + 1, 0);
    for (int i = bits - 1; i >= 0; --i) {
      remainder = remainder.ShiftLeft(1);
      if (Bit(i)) {
        if (remainder.limbs.empty()) remainder.limbs.push_back(0);
        remainder.limbs[0] |= 1u;
      }
      if (remainder.Compare(d) >= 0) {
        remainder.Sub(d);
        quotient.limbs[static_cast<size_t>(i) / 32] |= 1u << (i % 32);
      }
    }
    quotient.Trim();
    return quotient;
  }
};

// Round the big integer to a 64 bit normalized significand (round to nearest).
// Returns the significand and the binary exponent such that f * 2^e ~= value.
void NormalizeTo64(const BigUint& big, uint64_t& f, int& e) {
  const int bits = big.BitLength();
  if (bits <= 64) {
    f = big.Extract64(0);
    e = 0;
    while ((f >> 63u) == 0) {
      f <<= 1u;
      e--;
    }
    return;
  }
  const int shift = bits - 64;
  f = big.Extract64(shift);
  e = shift;
  if (big.Bit(shift - 1)) {
    if (f == 0xFFFFFFFFFFFFFFFFull) {
      f = uint64_t{1} << 63u;
      e += 1;
    } else {
      f += 1;
    }
  }
}

const std::vector<CachedPower>& CachedPowers() {
  static const std::vector<CachedPower> table = [] {
    std::vector<CachedPower> t;
    for (int k = -300; k <= 324; k += 8) {
      uint64_t f = 0;
      int e = 0;
      if (k >= 0) {
        NormalizeTo64(BigUint::Pow10(k), f, e);
      } else {
        // 10^k = 2^P / 10^-k ; choose P large enough so the quotient has > 64 significant bits.
        const int P = 64 + 4 * (-k) + 8;
        BigUint q = BigUint::Pow2(P).Div(BigUint::Pow10(-k));
        NormalizeTo64(q, f, e);
        e -= P;
      }
      t.push_back({f, e, k});
    }
    return t;
  }();
  return table;
}

CachedPower GetCachedPowerForBinaryExponent(int e) {
  constexpr int kCachedPowersMinDecExp = -300;
  constexpr int kCachedPowersDecStep = 8;
  const int f = kAlpha - e - 1;
  const int k = (f * 78913) / (1 << 18) + static_cast<int>(f > 0);
  const int index = (-kCachedPowersMinDecExp + k + (kCachedPowersDecStep - 1)) / kCachedPowersDecStep;
  return CachedPowers()[static_cast<size_t>(index)];
}

int FindLargestPow10(uint32_t n, uint32_t& pow10) {
  if (n >= 1000000000) { pow10 = 1000000000; return 10; }
  if (n >= 100000000) { pow10 = 100000000; return 9; }
  if (n >= 10000000) { pow10 = 10000000; return 8; }
  if (n >= 1000000) { pow10 = 1000000; return 7; }
  if (n >= 100000) { pow10 = 100000; return 6; }
  if (n >= 10000) { pow10 = 10000; return 5; }
  if (n >= 1000) { pow10 = 1000; return 4; }
  if (n >= 100) { pow10 = 100; return 3; }
  if (n >= 10) { pow10 = 10; return 2; }
  pow10 = 1;
  return 1;
}

void Grisu2Round(char* buf, int len, uint64_t dist, uint64_t delta, uint64_t rest, uint64_t ten_k) {
  while (rest < dist && delta - rest >= ten_k &&
         (rest + ten_k < dist || dist - rest > rest + ten_k - dist)) {
    buf[len - 1]--;
    rest += ten_k;
  }
}

void Grisu2DigitGen(char* buffer, int& length, int& decimal_exponent, DiyFp M_minus, DiyFp w,
                    DiyFp M_plus) {
  uint64_t delta = M_plus.f - M_minus.f;
  uint64_t dist = M_plus.f - w.f;
  const DiyFp one{uint64_t{1} << static_cast<unsigned>(-M_plus.e), M_plus.e};
  auto p1 = static_cast<uint32_t>(M_plus.f >> static_cast<unsigned>(-one.e));
  uint64_t p2 = M_plus.f & (one.f - 1);

  uint32_t pow10 = 0;
  const int k = FindLargestPow10(p1, pow10);
  int n = k;
  while (n > 0) {
    const uint32_t d = p1 / pow10;
    const uint32_t r = p1 % pow10;
    buffer[length++] = static_cast<char>('0' + d);
    p1 = r;
    n--;
    const uint64_t rest = (uint64_t{p1} << static_cast<unsigned>(-one.e)) + p2;
    if (rest <= delta) {
      decimal_exponent += n;
      const uint64_t ten_n = uint64_t{pow10} << static_cast<unsigned>(-one.e);
      Grisu2Round(buffer, length, dist, delta, rest, ten_n);
      return;
    }
    pow10 /= 10;
  }

  int m = 0;
  for (;;) {
    p2 *= 10;
    const uint64_t d = p2 >> static_cast<unsigned>(-one.e);
    const uint64_t r = p2 & (one.f - 1);
    buffer[length++] = static_cast<char>('0' + d);
    p2 = r;
    m++;
    delta *= 10;
    dist *= 10;
    if (p2 <= delta) break;
  }
  decimal_exponent -= m;
  const uint64_t ten_m = one.f;
  Grisu2Round(buffer, length, dist, delta, p2, ten_m);
}

void Grisu2(char* buf, int& len, int& decimal_exponent, DiyFp m_minus, DiyFp v, DiyFp m_plus) {
  const CachedPower cached = GetCachedPowerForBinaryExponent(m_plus.e);
  const DiyFp c_minus_k{cached.f, cached.e};
  const DiyFp w = DiyMul(v, c_minus_k);
  const DiyFp w_minus = DiyMul(m_minus, c_minus_k);
  const DiyFp w_plus = DiyMul(m_plus, c_minus_k);
  const DiyFp M_minus{w_minus.f + 1, w_minus.e};
  const DiyFp M_plus{w_plus.f - 1, w_plus.e};
  decimal_exponent = -cached.k;
  Grisu2DigitGen(buf, len, decimal_exponent, M_minus, w, M_plus);
}

char* AppendExponent(char* buf, int e) {
  if (e < 0) {
    e = -e;
    *buf++ = '-';
  } else {
    *buf++ = '+';
  }
  auto k = static_cast<uint32_t>(e);
  if (k < 10) {
    *buf++ = '0';
    *buf++ = static_cast<char>('0' + k);
  } else if (k < 100) {
    *buf++ = static_cast<char>('0' + k / 10);
    k %= 10;
    *buf++ = static_cast<char>('0' + k);
  } else {
    *buf++ = static_cast<char>('0' + k / 100);
    k %= 100;
    *buf++ = static_cast<char>('0' + k / 10);
    k %= 10;
    *buf++ = static_cast<char>('0' + k);
  }
  return buf;
}

char* FormatBuffer(char* buf, int len, int decimal_exponent, int min_exp, int max_exp) {
  const int k = len;
  const int n = len + decimal_exponent;
  if (k <= n && n <= max_exp) {
    std::memset(buf + k, '0', static_cast<size_t>(n - k));
    buf[n + 0] = '.';
    buf[n + 1] = '0';
    return buf + (n + 2);
  }
  if (0 < n && n <= max_exp) {
    std::memmove(buf + (n + 1), buf + n, static_cast<size_t>(k - n));
    buf[n] = '.';
    return buf + (k + 1);
  }
  if (min_exp < n && n <= 0) {
    std::memmove(buf + (2 + (-n)), buf, static_cast<size_t>(k));
    buf[0] = '0';
    buf[1] = '.';
    std::memset(buf + 2, '0', static_cast<size_t>(-n));
    return buf + (2 + (-n) + k);
  }
  if (k == 1) {
    buf += 1;
  } else {
    std::memmove(buf + 2, buf + 1, static_cast<size_t>(k - 1));
    buf[1] = '.';
    buf += 1 + k;
  }
  *buf++ = 'e';
  return AppendExponent(buf, n - 1);
}

}  // namespace

JsonPtr ParseJson(const std::string& input) {
  Parser parser(input);
  return parser.Parse();
}

std::string DumpDouble(double value) {
  char buf[64];
  char* first = buf;
  if (std::signbit(value)) {
    value = -value;
    *first++ = '-';
  }
  if (value == 0) {
    *first++ = '0';
    *first++ = '.';
    *first++ = '0';
    return std::string(buf, first);
  }
  int len = 0;
  int decimal_exponent = 0;
  const Boundaries w = ComputeBoundaries(value);
  Grisu2(first, len, decimal_exponent, w.minus, w.w, w.plus);
  char* end = FormatBuffer(first, len, decimal_exponent, -4, 15);
  return std::string(buf, end);
}

std::string DumpNumber(const JsonValue& value) {
  switch (value.type) {
    case JsonType::Integer: return std::to_string(value.integer);
    case JsonType::Unsigned: return std::to_string(value.unsigned_integer);
    case JsonType::Float: return DumpDouble(value.number);
    default: return "";
  }
}

}  // namespace jt
