using namespace jt;
void Dump(const JsonValue& v, int indent) {
  std::string pad(indent, ' ');
  switch (v.type) {
    case JsonType::Null: std::cout << "null"; break;
    case JsonType::Boolean: std::cout << (v.boolean ? "true" : "false"); break;
