    case JsonType::Object: std::cout << "{\n"; for (auto& kv : v.object) { std::cout << pad << "  \"" << kv.first << "\": "; Dump(*kv.second, indent+2); std::cout << ",\n"; } std::cout << pad << "}"; break;
    default: std::cout << DumpNumber(v);
  }
}
int main(int argc, char** argv) {
  std::stringstream ss;
  if (argc > 1) { std::ifstream f(argv[1]); ss << f.rdbuf(); } else ss << std::cin.rdbuf();
