bool InTable(const Interval* table, size_t size, uint32_t ucs) {
  size_t lo = 0;
  size_t hi = size;
  while (lo < hi) {
    const size_t mid = (lo + hi) / 2;
    if (ucs < table[mid].first) {
      hi = mid;
    } else if (ucs > table[mid].last) {
      lo = mid + 1;
    } else {
      return true;
    }
  }
  return false;
}

bool IsControl(uint32_t ucs) {
  if (ucs == 0) return true;
  if (ucs < 32) return ucs != 10;  // line feed is kept
  if (ucs >= 0x7F && ucs < 0xA0) return true;
  return false;
}

bool IsCombining(uint32_t ucs) {
  return InTable(kCombining, sizeof(kCombining) / sizeof(kCombining[0]), ucs);
}

bool IsFullWidth(uint32_t ucs) {
  if (ucs < 0x0300) return false;
  return InTable(kFullWidth, sizeof(kFullWidth) / sizeof(kFullWidth[0]), ucs);
}

bool EatCodePoint(const std::string& input, size_t start, size_t* end, uint32_t* ucs) {
  if (start >= input.size()) {
    *end = start + 1;
    return false;
  }
  const uint8_t c0 = static_cast<uint8_t>(input[start]);
  if ((c0 & 0x80) == 0) {
    *ucs = c0;
    *end = start + 1;
    return true;
  }
  if ((c0 & 0xE0) == 0xC0 && start + 1 < input.size()) {
    const uint8_t c1 = static_cast<uint8_t>(input[start + 1]);
    *ucs = ((c0 & 0x1F) << 6) | (c1 & 0x3F);
    *end = start + 2;
    return true;
  }
  if ((c0 & 0xF0) == 0xE0 && start + 2 < input.size()) {
    const uint8_t c1 = static_cast<uint8_t>(input[start + 1]);
    const uint8_t c2 = static_cast<uint8_t>(input[start + 2]);
    *ucs = ((c0 & 0x0F) << 12) | ((c1 & 0x3F) << 6) | (c2 & 0x3F);
    *end = start + 3;
    return true;
  }
  if ((c0 & 0xF8) == 0xF0 && start + 3 < input.size()) {
    const uint8_t c1 = static_cast<uint8_t>(input[start + 1]);
    const uint8_t c2 = static_cast<uint8_t>(input[start + 2]);
    const uint8_t c3 = static_cast<uint8_t>(input[start + 3]);
    *ucs = ((c0 & 0x07) << 18) | ((c1 & 0x3F) << 12) | ((c2 & 0x3F) << 6) | (c3 & 0x3F);
    *end = start + 4;
    return true;
  }
  *end = start + 1;
  return false;
}

}  // namespace

int string_width(const std::string& input) {
  int width = 0;
  size_t start = 0;
  while (start < input.size()) {
    uint32_t codepoint = 0;
    if (!EatCodePoint(input, start, &start, &codepoint)) continue;
    if (IsControl(codepoint)) continue;
    if (IsCombining(codepoint)) continue;
    if (IsFullWidth(codepoint)) {
      width += 2;
      continue;
    }
    width += 1;
  }
  return width;
}

std::vector<std::string> Utf8ToGlyphs(const std::string& input) {
  std::vector<std::string> out;
  out.reserve(input.size());
  size_t start = 0;
  size_t end = 0;
  while (start < input.size()) {
    uint32_t codepoint = 0;
    const bool eaten = EatCodePoint(input, start, &end, &codepoint);
    if (!eaten || IsControl(codepoint)) {
      start = end;
      continue;
    }
    if (IsCombining(codepoint)) {
      if (!out.empty()) out.back() += input.substr(start, end - start);
      start = end;
      continue;
    }
    if (IsFullWidth(codepoint)) {
      out.push_back(input.substr(start, end - start));
      out.emplace_back("");
      start = end;
      continue;
    }
    out.push_back(input.substr(start, end - start));
    start = end;
  }
  return out;
}

// ---------------------------------------------------------------------------
// Box / Color / Screen
// ---------------------------------------------------------------------------
Box Box::Intersection(Box a, Box b) {
  return Box{std::max(a.x_min, b.x_min), std::min(a.x_max, b.x_max), std::max(a.y_min, b.y_min),
             std::min(a.y_max, b.y_max)};
}

std::string Color::Print(bool background) const {
  if (index < 0) return background ? "49" : "39";
  if (index < 8) return std::to_string((background ? 40 : 30) + index);
  return std::to_string((background ? 100 : 90) + index - 8);
}

Screen::Screen(int dimx, int dimy)
    : stencil{0, dimx - 1, 0, dimy - 1},
      dimx_(dimx),
      dimy_(dimy),
      pixels_(static_cast<size_t>(dimy), std::vector<Pixel>(static_cast<size_t>(dimx))) {
  cursor_.x = dimx_ - 1;
  cursor_.y = dimy_ - 1;
}

Pixel& Screen::PixelAt(int x, int y) {
  static Pixel dev_null;
  if (stencil.Contain(x, y)) return pixels_[static_cast<size_t>(y)][static_cast<size_t>(x)];
  dev_null = Pixel();
  return dev_null;
}

void Screen::Clear() {
  pixels_ = std::vector<std::vector<Pixel>>(static_cast<size_t>(dimy_),
                                            std::vector<Pixel>(static_cast<size_t>(dimx_)));
  cursor_.x = dimx_ - 1;
  cursor_.y = dimy_ - 1;
}

std::string Screen::ResetPosition(bool clear) const {
  std::string out;
  if (clear) {
    out += "\r\x1b[2K";
    for (int y = 1; y < dimy_; ++y) out += "\x1b[1A\x1b[2K";
  } else {
    out += "\r";
    for (int y = 1; y < dimy_; ++y) out += "\x1b[1A";
  }
  return out;
}

namespace {
void UpdatePixelStyle(std::string& out, Pixel& prev, const Pixel& next) {
  if (next.bold != prev.bold || next.dim != prev.dim) {
    if ((!next.bold && prev.bold) || (!next.dim && prev.dim)) out += "\x1b[22m";
    if (next.bold) out += "\x1b[1m";
    if (next.dim) out += "\x1b[2m";
  }
  if (next.underlined != prev.underlined) out += next.underlined ? "\x1b[4m" : "\x1b[24m";
  if (next.blink != prev.blink) out += next.blink ? "\x1b[5m" : "\x1b[25m";
  if (next.inverted != prev.inverted) out += next.inverted ? "\x1b[7m" : "\x1b[27m";
  if (next.strikethrough != prev.strikethrough) out += next.strikethrough ? "\x1b[9m" : "\x1b[29m";
  if (next.foreground != prev.foreground || next.background != prev.background) {
    out += "\x1b[" + next.foreground.Print(false) + "m";
    out += "\x1b[" + next.background.Print(true) + "m";
  }
  prev = next;
}
}  // namespace

std::string Screen::ToString() const {
  std::string out;
  Pixel previous;
  const Pixel final_pixel;
  for (int y = 0; y < dimy_; ++y) {
    if (y != 0) out += "\r\n";
    bool previous_fullwidth = false;
    for (const auto& pixel : pixels_[static_cast<size_t>(y)]) {
      if (!previous_fullwidth) {
        UpdatePixelStyle(out, previous, pixel);
        out += pixel.character;
      }
      previous_fullwidth = (string_width(pixel.character) == 2);
    }
  }
  UpdatePixelStyle(out, previous, final_pixel);
  return out;
}

// ---------------------------------------------------------------------------
// box_helper
// ---------------------------------------------------------------------------
namespace box_helper {
namespace {
void ComputeGrow(std::vector<Element>* elements, int extra_space, int flex_grow_sum) {
  for (Element& element : *elements) {
    const int added_space = extra_space * element.flex_grow / std::max(flex_grow_sum, 1);
    extra_space -= added_space;
    flex_grow_sum -= element.flex_grow;
    element.size = element.min_size + added_space;
  }
}

void ComputeShrinkEasy(std::vector<Element>* elements, int extra_space, int flex_shrink_sum) {
  for (Element& element : *elements) {
    const int added_space =
        extra_space * element.min_size * element.flex_shrink / std::max(flex_shrink_sum, 1);
    extra_space -= added_space;
    flex_shrink_sum -= element.flex_shrink * element.min_size;
    element.size = element.min_size + added_space;
  }
}

void ComputeShrinkHard(std::vector<Element>* elements, int extra_space, int size) {
  for (Element& element : *elements) {
    if (element.flex_shrink != 0) {
      element.size = 0;
      continue;
    }
    const int added_space = extra_space * element.min_size / std::max(1, size);
    extra_space -= added_space;
    size -= element.min_size;
    element.size = element.min_size + added_space;
  }
}
}  // namespace

void Compute(std::vector<Element>* elements, int target_size) {
  int size = 0;
  int flex_grow_sum = 0;
  int flex_shrink_sum = 0;
  int flex_shrink_size = 0;
  for (auto& element : *elements) {
    flex_grow_sum += element.flex_grow;
    flex_shrink_sum += element.min_size * element.flex_shrink;
    if (element.flex_shrink != 0) flex_shrink_size += element.min_size;
    size += element.min_size;
  }
  const int extra_space = target_size - size;
  if (extra_space >= 0) {
    ComputeGrow(elements, extra_space, flex_grow_sum);
  } else if (flex_shrink_size + extra_space >= 0) {
    ComputeShrinkEasy(elements, extra_space, flex_shrink_sum);
  } else {
    ComputeShrinkHard(elements, extra_space + flex_shrink_size, size - flex_shrink_size);
  }
}
}  // namespace box_helper

// ---------------------------------------------------------------------------
// Node
// ---------------------------------------------------------------------------
void Node::ComputeRequirement() {
  for (auto& child : children_) child->ComputeRequirement();
}

void Node::SetBox(Box box) { box_ = box; }

void Node::Render(Screen& screen) {
  for (auto& child : children_) child->Render(screen);
}

void Node::Check(Status* status) {
  for (auto& child : children_) child->Check(status);
  status->need_iteration |= (status->iteration == 0);
}

void Render(Screen& screen, Node* node) {
  Box box;
  box.x_min = 0;
  box.y_min = 0;
  box.x_max = screen.dimx() - 1;
  box.y_max = screen.dimy() - 1;

  Node::Status status;
  node->Check(&status);
  const int max_iterations = 20;
  while (status.need_iteration && status.iteration < max_iterations) {
    node->ComputeRequirement();
    node->SetBox(box);
    status.need_iteration = false;
    status.iteration++;
    node->Check(&status);
  }
  screen.stencil = box;
  node->Render(screen);
}

