namespace {

class Text : public Node {
 public:
  explicit Text(std::string s) : text_(std::move(s)) {}
  void ComputeRequirement() override {
    requirement_.min_x = string_width(text_);
    requirement_.min_y = 1;
  }
  void Render(Screen& screen) override {
    int x = box_.x_min;
    const int y = box_.y_min;
    if (y > box_.y_max) return;
    for (const auto& cell : Utf8ToGlyphs(text_)) {
      if (x > box_.x_max) return;
      if (cell == "\n") continue;
      screen.PixelAt(x, y).character = cell;
      ++x;
    }
  }

 private:
  std::string text_;
};

class Empty : public Node {
 public:
  void ComputeRequirement() override { requirement_ = Requirement(); }
};

class HBox : public Node {
 public:
  explicit HBox(Elements children) : Node(std::move(children)) {}
  void ComputeRequirement() override {
    requirement_ = Requirement();
    for (auto& child : children_) {
      child->ComputeRequirement();
      if (requirement_.selection < child->requirement().selection) {
        requirement_.selection = child->requirement().selection;
        requirement_.selected_box = child->requirement().selected_box;
        requirement_.selected_box.x_min += requirement_.min_x;
        requirement_.selected_box.x_max += requirement_.min_x;
      }
      requirement_.min_x += child->requirement().min_x;
      requirement_.min_y = std::max(requirement_.min_y, child->requirement().min_y);
    }
  }
  void SetBox(Box box) override {
    Node::SetBox(box);
    std::vector<box_helper::Element> elements(children_.size());
    for (size_t i = 0; i < children_.size(); ++i) {
      const auto& r = children_[i]->requirement();
      elements[i].min_size = r.min_x;
      elements[i].flex_grow = r.flex_grow_x;
      elements[i].flex_shrink = r.flex_shrink_x;
    }
    const int target_size = box.x_max - box.x_min + 1;
    box_helper::Compute(&elements, target_size);
    int x = box.x_min;
    for (size_t i = 0; i < children_.size(); ++i) {
      box.x_min = x;
      box.x_max = x + elements[i].size - 1;
      children_[i]->SetBox(box);
      x = box.x_max + 1;
    }
  }
};

class VBox : public Node {
 public:
  explicit VBox(Elements children) : Node(std::move(children)) {}
  void ComputeRequirement() override {
    requirement_ = Requirement();
    for (auto& child : children_) {
      child->ComputeRequirement();
      if (requirement_.selection < child->requirement().selection) {
        requirement_.selection = child->requirement().selection;
        requirement_.selected_box = child->requirement().selected_box;
        requirement_.selected_box.y_min += requirement_.min_y;
        requirement_.selected_box.y_max += requirement_.min_y;
      }
      requirement_.min_y += child->requirement().min_y;
      requirement_.min_x = std::max(requirement_.min_x, child->requirement().min_x);
    }
  }
  void SetBox(Box box) override {
    Node::SetBox(box);
    std::vector<box_helper::Element> elements(children_.size());
    for (size_t i = 0; i < children_.size(); ++i) {
      const auto& r = children_[i]->requirement();
      elements[i].min_size = r.min_y;
      elements[i].flex_grow = r.flex_grow_y;
      elements[i].flex_shrink = r.flex_shrink_y;
    }
    const int target_size = box.y_max - box.y_min + 1;
    box_helper::Compute(&elements, target_size);
    int y = box.y_min;
    for (size_t i = 0; i < children_.size(); ++i) {
      box.y_min = y;
      box.y_max = y + elements[i].size - 1;
      children_[i]->SetBox(box);
      y = box.y_max + 1;
    }
  }
};

// Row-oriented wrapping flow layout with a horizontal gap of one cell.
class Flexbox : public Node {
 public:
  explicit Flexbox(Elements children) : Node(std::move(children)) {}

  struct Block {
    int min_size_x = 0;
    int min_size_y = 0;
    int x = 0;
    int y = 0;
    int dimx = 0;
    int dimy = 0;
  };

  void Layout(int size_x) {
    blocks_.clear();
    for (auto& child : children_) {
      Block b;
      b.min_size_x = child->requirement().min_x;
      b.min_size_y = child->requirement().min_y;
      blocks_.push_back(b);
    }
    const int gap_x = 1;
    // Step 1: distribute the blocks into lines.
    std::vector<std::vector<Block*>> lines;
    {
      std::vector<Block*> line;
      int x = 0;
      for (auto& block : blocks_) {
        if (x + block.min_size_x > size_x) {
          x = 0;
          if (!line.empty()) lines.push_back(std::move(line));
          line = std::vector<Block*>();
        }
        line.push_back(&block);
        x += block.min_size_x + gap_x;
      }
      if (!line.empty()) lines.push_back(std::move(line));
    }
    // Step 2: X positions.
    for (auto& line : lines) {
      std::vector<box_helper::Element> elements;
      for (auto* block : line) {
        box_helper::Element e;
        e.min_size = block->min_size_x;
        elements.push_back(e);
      }
      box_helper::Compute(&elements, size_x - gap_x * (static_cast<int>(line.size()) - 1));
      int x = 0;
      for (size_t i = 0; i < line.size(); ++i) {
        line[i]->dimx = elements[i].size;
        line[i]->x = x;
        x += elements[i].size + gap_x;
      }
    }
    // Step 3: Y positions.
    int y = 0;
    for (auto& line : lines) {
      int dimy = 0;
      for (auto* block : line) dimy = std::max(dimy, block->min_size_y);
      for (auto* block : line) {
        block->y = y;
        block->dimy = block->min_size_y;
      }
      y += dimy;
    }
  }

  void ComputeRequirement() override {
    for (auto& child : children_) child->ComputeRequirement();
    Layout(asked_);
    requirement_ = Requirement();
    if (blocks_.empty()) return;
    Box box;
    box.x_min = blocks_[0].x;
    box.y_min = blocks_[0].y;
    box.x_max = blocks_[0].x + blocks_[0].dimx;
    box.y_max = blocks_[0].y + blocks_[0].dimy;
    for (auto& b : blocks_) {
      box.x_min = std::min(box.x_min, b.x);
      box.y_min = std::min(box.y_min, b.y);
      box.x_max = std::max(box.x_max, b.x + b.dimx);
      box.y_max = std::max(box.y_max, b.y + b.dimy);
    }
    requirement_.min_x = box.x_max - box.x_min;
    requirement_.min_y = box.y_max - box.y_min;
    for (size_t i = 0; i < children_.size(); ++i) {
      if (requirement_.selection >= children_[i]->requirement().selection) continue;
      requirement_.selection = children_[i]->requirement().selection;
      Box selected_box = children_[i]->requirement().selected_box;
      auto& b = blocks_[i];
      selected_box.x_min += b.x;
      selected_box.y_min += b.y;
      selected_box.x_max += b.x;
      selected_box.y_max += b.y;
      requirement_.selected_box = Box::Intersection(selected_box, box);
    }
  }

  void SetBox(Box box) override {
    Node::SetBox(box);
    const int asked_previous = asked_;
    asked_ = std::min(asked_, box.x_max - box.x_min + 1);
    need_iteration_ = (asked_ != asked_previous);
    Layout(last_layout_size_);
    for (size_t i = 0; i < children_.size(); ++i) {
      auto& b = blocks_[i];
      Box children_box;
      children_box.x_min = box.x_min + b.x;
      children_box.y_min = box.y_min + b.y;
      children_box.x_max = box.x_min + b.x + b.dimx - 1;
      children_box.y_max = box.y_min + b.y + b.dimy - 1;
      Box intersection = Box::Intersection(box, children_box);
      children_[i]->SetBox(intersection);
      need_iteration_ |= (intersection != children_box);
    }
  }

  void Check(Status* status) override {
    for (auto& child : children_) child->Check(status);
    if (status->iteration == 0) {
      asked_ = 6000;
      need_iteration_ = true;
    }
    status->need_iteration |= need_iteration_;
  }

 private:
  // Layout uses the width asked at the time of ComputeRequirement.
  void LayoutWrapper();
  std::vector<Block> blocks_;
  int asked_ = 6000;
  int last_layout_size_ = 6000;
  bool need_iteration_ = false;

  friend Element jt::paragraph(const std::string&);
};

class GridBox : public Node {
 public:
  explicit GridBox(std::vector<Elements> lines) : lines_(std::move(lines)) {
    y_size_ = static_cast<int>(lines_.size());
    for (const auto& line : lines_) x_size_ = std::max(x_size_, static_cast<int>(line.size()));
    for (auto& line : lines_) {
      while (static_cast<int>(line.size()) < x_size_) line.push_back(emptyElement());
    }
  }

  void ComputeRequirement() override {
    requirement_ = Requirement();
    for (auto& line : lines_)
      for (auto& cell : line) cell->ComputeRequirement();
    std::vector<int> size_x(static_cast<size_t>(x_size_), 0);
    std::vector<int> size_y(static_cast<size_t>(y_size_), 0);
    for (int x = 0; x < x_size_; ++x) {
      for (int y = 0; y < y_size_; ++y) {
        const auto& r = lines_[static_cast<size_t>(y)][static_cast<size_t>(x)]->requirement();
        size_x[static_cast<size_t>(x)] = std::max(size_x[static_cast<size_t>(x)], r.min_x);
        size_y[static_cast<size_t>(y)] = std::max(size_y[static_cast<size_t>(y)], r.min_y);
      }
    }
    // Prefix sums (offsets) and totals.
    int total_x = 0;
    for (auto& v : size_x) {
      const int old = total_x;
      total_x += v;
      v = old;
    }
    int total_y = 0;
    for (auto& v : size_y) {
      const int old = total_y;
      total_y += v;
      v = old;
    }
    requirement_.min_x = total_x;
    requirement_.min_y = total_y;
    for (int x = 0; x < x_size_; ++x) {
      for (int y = 0; y < y_size_; ++y) {
        const auto& r = lines_[static_cast<size_t>(y)][static_cast<size_t>(x)]->requirement();
        if (requirement_.selection >= r.selection) continue;
        requirement_.selection = r.selection;
        Box selected_box = r.selected_box;
        selected_box.x_min += size_x[static_cast<size_t>(x)];
        selected_box.x_max += size_x[static_cast<size_t>(x)];
        selected_box.y_min += size_y[static_cast<size_t>(y)];
        selected_box.y_max += size_y[static_cast<size_t>(y)];
        requirement_.selected_box = selected_box;
      }
    }
  }

  void SetBox(Box box) override {
    Node::SetBox(box);
    std::vector<box_helper::Element> elements_x(static_cast<size_t>(x_size_));
    std::vector<box_helper::Element> elements_y(static_cast<size_t>(y_size_));
    for (auto& e : elements_x) e.flex_grow = e.flex_shrink = 1 << 20;
    for (auto& e : elements_y) e.flex_grow = e.flex_shrink = 1 << 20;
    for (int y = 0; y < y_size_; ++y) {
      for (int x = 0; x < x_size_; ++x) {
        const auto& r = lines_[static_cast<size_t>(y)][static_cast<size_t>(x)]->requirement();
        auto& e_x = elements_x[static_cast<size_t>(x)];
        auto& e_y = elements_y[static_cast<size_t>(y)];
        e_x.min_size = std::max(e_x.min_size, r.min_x);
        e_y.min_size = std::max(e_y.min_size, r.min_y);
        e_x.flex_grow = std::min(e_x.flex_grow, r.flex_grow_x);
        e_y.flex_grow = std::min(e_y.flex_grow, r.flex_grow_y);
        e_x.flex_shrink = std::min(e_x.flex_shrink, r.flex_shrink_x);
        e_y.flex_shrink = std::min(e_y.flex_shrink, r.flex_shrink_y);
      }
    }
    const int target_x = box.x_max - box.x_min + 1;
    const int target_y = box.y_max - box.y_min + 1;
    box_helper::Compute(&elements_x, target_x);
    box_helper::Compute(&elements_y, target_y);

    int y = box.y_min;
    for (int iy = 0; iy < y_size_; ++iy) {
      Box row_box = box;
      row_box.y_min = y;
      row_box.y_max = y + elements_y[static_cast<size_t>(iy)].size - 1;
      int x = box.x_min;
      for (int ix = 0; ix < x_size_; ++ix) {
        Box cell_box = row_box;
        cell_box.x_min = x;
        cell_box.x_max = x + elements_x[static_cast<size_t>(ix)].size - 1;
        lines_[static_cast<size_t>(iy)][static_cast<size_t>(ix)]->SetBox(cell_box);
        x = cell_box.x_max + 1;
      }
      y = row_box.y_max + 1;
    }
  }

  void Render(Screen& screen) override {
    for (auto& line : lines_)
      for (auto& cell : line) cell->Render(screen);
  }

  void Check(Status* status) override {
    for (auto& line : lines_)
      for (auto& cell : line) cell->Check(status);
    status->need_iteration |= (status->iteration == 0);
  }

 private:
  std::vector<Elements> lines_;
  int x_size_ = 0;
  int y_size_ = 0;
};

class Separator : public Node {
 public:
  explicit Separator(std::string value) : value_(std::move(value)) {}
  void ComputeRequirement() override {
    requirement_ = Requirement();
    requirement_.min_x = 1;
    requirement_.min_y = 1;
  }
  void Render(Screen& screen) override {
    for (int y = box_.y_min; y <= box_.y_max; ++y)
      for (int x = box_.x_min; x <= box_.x_max; ++x) screen.PixelAt(x, y).character = value_;
  }

 private:
  std::string value_;
};

class NodeDecorator : public Node {
 public:
  explicit NodeDecorator(Element child) : Node({std::move(child)}) {}
  void ComputeRequirement() override {
    Node::ComputeRequirement();
    requirement_ = children_[0]->requirement();
  }
  void SetBox(Box box) override {
    Node::SetBox(box);
    children_[0]->SetBox(box);
  }
};

class ColorDecorator : public NodeDecorator {
 public:
  ColorDecorator(Element child, Color c) : NodeDecorator(std::move(child)), color_(c) {}
  void Render(Screen& screen) override {
    Node::Render(screen);
    for (int y = box_.y_min; y <= box_.y_max; ++y)
      for (int x = box_.x_min; x <= box_.x_max; ++x) screen.PixelAt(x, y).foreground = color_;
  }

 private:
  Color color_;
};

class Bold : public NodeDecorator {
 public:
  using NodeDecorator::NodeDecorator;
  void Render(Screen& screen) override {
    Node::Render(screen);
    for (int y = box_.y_min; y <= box_.y_max; ++y)
      for (int x = box_.x_min; x <= box_.x_max; ++x) screen.PixelAt(x, y).bold = true;
  }
};

class Inverted : public NodeDecorator {
 public:
  using NodeDecorator::NodeDecorator;
  void Render(Screen& screen) override {
    Node::Render(screen);
    for (int y = box_.y_min; y <= box_.y_max; ++y)
      for (int x = box_.x_min; x <= box_.x_max; ++x) screen.PixelAt(x, y).inverted = true;
  }
};

class Select : public NodeDecorator {
 public:
  using NodeDecorator::NodeDecorator;
  void ComputeRequirement() override {
    NodeDecorator::ComputeRequirement();
    auto& sb = requirement_.selected_box;
    sb.x_min = 0;
    sb.y_min = 0;
    sb.x_max = requirement_.min_x - 1;
    sb.y_max = requirement_.min_y - 1;
    requirement_.selection = Requirement::SELECTED;
  }
};

class Focus : public Select {
 public:
  using Select::Select;
  void ComputeRequirement() override {
    Select::ComputeRequirement();
    requirement_.selection = Requirement::FOCUSED;
  }
  void Render(Screen& screen) override {
    Select::Render(screen);
    screen.SetCursor(Screen::Cursor{box_.x_max, box_.y_max, Screen::Cursor::Hidden});
  }
};

class Reflect : public Node {
 public:
  Reflect(Element child, Box& box) : Node({std::move(child)}), reflected_box_(box) {}
  void ComputeRequirement() override {
    Node::ComputeRequirement();
    requirement_ = children_[0]->requirement();
  }
  void SetBox(Box box) override {
    reflected_box_ = box;
    Node::SetBox(box);
    children_[0]->SetBox(box);
  }
  void Render(Screen& screen) override {
    reflected_box_ = Box::Intersection(screen.stencil, reflected_box_);
    Node::Render(screen);
  }

 private:
  Box& reflected_box_;
};

class FlexDecorator : public Node {
 public:
  FlexDecorator(Element child, int gx, int gy, int sx, int sy)
      : Node({std::move(child)}), gx_(gx), gy_(gy), sx_(sx), sy_(sy) {}
  void ComputeRequirement() override {
    Node::ComputeRequirement();
    requirement_ = children_[0]->requirement();
    if (gx_ >= 0) requirement_.flex_grow_x = gx_;
    if (gy_ >= 0) requirement_.flex_grow_y = gy_;
    if (sx_ >= 0) requirement_.flex_shrink_x = sx_;
    if (sy_ >= 0) requirement_.flex_shrink_y = sy_;
  }
  void SetBox(Box box) override {
    Node::SetBox(box);
    children_[0]->SetBox(box);
  }

 private:
  int gx_, gy_, sx_, sy_;
};

class Frame : public Node {
 public:
  Frame(Element child, bool x_frame, bool y_frame)
      : Node({std::move(child)}), x_frame_(x_frame), y_frame_(y_frame) {}
  void ComputeRequirement() override {
    Node::ComputeRequirement();
    requirement_ = children_[0]->requirement();
  }
  void SetBox(Box box) override {
    Node::SetBox(box);
    auto& child = children_[0];
    Box children_box = box;
    if (x_frame_) {
      const int external_dimx = box.x_max - box.x_min;
      const int internal_dimx = std::max(requirement_.min_x, external_dimx);
      const int focused_dimx = requirement_.selected_box.x_max - requirement_.selected_box.x_min;
      int dx = requirement_.selected_box.x_min - external_dimx / 2 + focused_dimx / 2;
      dx = std::max(0, std::min(internal_dimx - external_dimx - 1, dx));
      children_box.x_min = box.x_min - dx;
      children_box.x_max = box.x_min + internal_dimx - dx;
    }
    if (y_frame_) {
      const int external_dimy = box.y_max - box.y_min;
      const int internal_dimy = std::max(requirement_.min_y, external_dimy);
      const int focused_dimy = requirement_.selected_box.y_max - requirement_.selected_box.y_min;
      int dy = requirement_.selected_box.y_min - external_dimy / 2 + focused_dimy / 2;
      dy = std::max(0, std::min(internal_dimy - external_dimy - 1, dy));
      children_box.y_min = box.y_min - dy;
      children_box.y_max = box.y_min + internal_dimy - dy;
    }
    child->SetBox(children_box);
  }
  void Render(Screen& screen) override {
    if (requirement_.min_x <= box_.x_max - box_.x_min + 1 &&
        requirement_.min_y <= box_.y_max - box_.y_min + 1) {
      Node::Render(screen);
      return;
    }
    const Box old_stencil = screen.stencil;
    screen.stencil = Box::Intersection(box_, screen.stencil);
    Node::Render(screen);
    screen.stencil = old_stencil;
  }

 private:
  bool x_frame_;
  bool y_frame_;
};

