Element text(std::string s) { return std::make_shared<Text>(std::move(s)); }
Element emptyElement() { return std::make_shared<Empty>(); }
Element hbox(Elements children) { return std::make_shared<HBox>(std::move(children)); }
Element vbox(Elements children) { return std::make_shared<VBox>(std::move(children)); }
Element gridbox(std::vector<Elements> lines) { return std::make_shared<GridBox>(std::move(lines)); }
Element separatorCharacter(std::string c) { return std::make_shared<Separator>(std::move(c)); }

Element paragraph(const std::string& s) {
  Elements words;
  std::stringstream ss(s);
  std::string word;
  while (std::getline(ss, word, ' ')) words.push_back(text(word));
  return std::make_shared<Flexbox>(std::move(words));
}

