#include "component.h"

#include <algorithm>

namespace jt {

ComponentBase::~ComponentBase() { DetachAllChildren(); }

Element ComponentBase::Render() {
  if (children_.size() == 1) return children_[0]->Render();
  return text("Not implemented component");
}

bool ComponentBase::OnEvent(Event event) {
  for (auto& child : children_) {
    if (child->OnEvent(event)) return true;
  }
  return false;
}

ComponentBase* ComponentBase::ActiveChild() {
  for (auto& child : children_) {
    if (child->Focusable()) return child.get();
  }
  return nullptr;
}

bool ComponentBase::Focusable() const {
  for (const auto& child : children_) {
    if (child->Focusable()) return true;
  }
  return false;
}

void ComponentBase::SetActiveChild(ComponentBase*) {}

bool ComponentBase::Active() const {
  return parent_ == nullptr || parent_->ActiveChild() == this;
}

bool ComponentBase::Focused() const {
  const ComponentBase* current = this;
  while (current && current->Active()) current = current->parent_;
  return current == nullptr;
}

void ComponentBase::TakeFocus() {
  ComponentBase* child = this;
  while (ComponentBase* parent = child->parent_) {
    parent->SetActiveChild(child);
    child = parent;
  }
}

void ComponentBase::Add(Component child) {
  child->parent_ = this;
  children_.push_back(std::move(child));
}

void ComponentBase::DetachAllChildren() {
  for (auto& child : children_) child->parent_ = nullptr;
  children_.clear();
}

// ---------------------------------------------------------------------------
// Containers
// ---------------------------------------------------------------------------
ContainerBase::ContainerBase(Components children, int* selector)
    : selector_(selector ? selector : &selected_) {
  for (auto& child : children) Add(std::move(child));
}

bool ContainerBase::OnEvent(Event event) {
  if (event.is_mouse()) return OnMouseEvent(event);
  if (!Focused()) return false;
  if (ActiveChild() && ActiveChild()->OnEvent(event)) return true;
  return EventHandler(event);
}

bool ContainerBase::OnMouseEvent(Event event) { return ComponentBase::OnEvent(event); }

ComponentBase* ContainerBase::ActiveChild() {
  if (children_.empty()) return nullptr;
  return children_[static_cast<size_t>(*selector_) % children_.size()].get();
}

void ContainerBase::SetActiveChild(ComponentBase* child) {
  for (size_t i = 0; i < children_.size(); ++i) {
    if (children_[i].get() == child) {
      *selector_ = static_cast<int>(i);
      return;
    }
  }
}

void ContainerBase::MoveSelector(int dir) {
  for (int i = *selector_ + dir; i >= 0 && i < static_cast<int>(children_.size()); i += dir) {
    if (children_[static_cast<size_t>(i)]->Focusable()) {
      *selector_ = i;
      return;
    }
  }
}

void ContainerBase::MoveSelectorWrap(int dir) {
  if (children_.empty()) return;
  const int n = static_cast<int>(children_.size());
  for (int offset = 1; offset < n; ++offset) {
    const int i = ((*selector_ + offset * dir) % n + n) % n;
    if (children_[static_cast<size_t>(i)]->Focusable()) {
      *selector_ = i;
      return;
    }
  }
}

Element VerticalContainer::Render() {
  Elements elements;
  for (auto& child : children_) elements.push_back(child->Render());
  if (elements.empty()) return reflect(box_, text("Empty container"));
  return reflect(box_, vbox(std::move(elements)));
}

bool VerticalContainer::EventHandler(Event event) {
  const int old_selected = *selector_;
  if (event == Event::ArrowUp() || event == Event::Character('k')) MoveSelector(-1);
  if (event == Event::ArrowDown() || event == Event::Character('j')) MoveSelector(+1);
  if (event == Event::PageUp()) {
    for (int i = 0; i < box_.y_max - box_.y_min; ++i) MoveSelector(-1);
  }
  if (event == Event::PageDown()) {
    for (int i = 0; i < box_.y_max - box_.y_min; ++i) MoveSelector(1);
  }
  if (event == Event::Home()) {
    for (size_t i = 0; i < children_.size(); ++i) MoveSelector(-1);
  }
  if (event == Event::End()) {
    for (size_t i = 0; i < children_.size(); ++i) MoveSelector(+1);
  }
  if (event == Event::Tab()) MoveSelectorWrap(+1);
  if (event == Event::TabReverse()) MoveSelectorWrap(-1);
  *selector_ = std::max(0, std::min(static_cast<int>(children_.size()) - 1, *selector_));
  return old_selected != *selector_;
}

bool VerticalContainer::OnMouseEvent(Event event) {
  if (ContainerBase::OnMouseEvent(event)) return true;
  if (event.mouse().button != Mouse::WheelUp && event.mouse().button != Mouse::WheelDown) return false;
  if (!box_.Contain(event.mouse().x, event.mouse().y)) return false;
  if (event.mouse().button == Mouse::WheelUp) MoveSelector(-1);
  if (event.mouse().button == Mouse::WheelDown) MoveSelector(+1);
  *selector_ = std::max(0, std::min(static_cast<int>(children_.size()) - 1, *selector_));
  return true;
}

Element HorizontalContainer::Render() {
  Elements elements;
  for (auto& child : children_) elements.push_back(child->Render());
  if (elements.empty()) return reflect(box_, text("Empty container"));
  return reflect(box_, hbox(std::move(elements)));
}

bool HorizontalContainer::EventHandler(Event event) {
  const int old_selected = *selector_;
  if (event == Event::ArrowLeft() || event == Event::Character('h')) MoveSelector(-1);
  if (event == Event::ArrowRight() || event == Event::Character('l')) MoveSelector(+1);
  if (event == Event::Tab()) MoveSelectorWrap(+1);
  if (event == Event::TabReverse()) MoveSelectorWrap(-1);
