void InputParser::Add(char c) {
  pending_ += c;
  timeout_ = 0;
  position_ = -1;
  Output output = Parse();
  switch (output.type) {
    case Uncompleted: return;
    case Drop: pending_.clear(); return;
    case Character: sink_(Event::Character(pending_)); pending_.clear(); return;
    case Special: sink_(Event::Special(pending_)); pending_.clear(); return;
    case MouseT: sink_(Event::MouseEvent(pending_, output.mouse)); pending_.clear(); return;
    case CursorPositionT:
      sink_(Event::CursorPosition(pending_, output.cursor_x, output.cursor_y));
      pending_.clear();
      return;
    case CursorShapeT: sink_(Event::CursorShape(pending_, output.cursor_shape)); pending_.clear(); return;
  }
}

void InputParser::Timeout(int milliseconds) {
  timeout_ += milliseconds;
  if (timeout_ < 50) return;
  timeout_ = 0;
  if (pending_.empty()) return;
  sink_(Event::Special(pending_));
  pending_.clear();
}

bool InputParser::Eat() {
  position_++;
  return position_ < static_cast<int>(pending_.size());
}

InputParser::Output InputParser::Parse() {
  if (!Eat()) return Uncompleted;
  switch (Current()) {
    case 24:
    case 26: return Drop;
    case 0x1b: return ParseESC();
    default: break;
  }
  if (Current() < 32) return Special;
  if (Current() == 127) return Special;
  return ParseUTF8();
}

InputParser::Output InputParser::ParseUTF8() {
  unsigned char head = Current();
  unsigned char selector = 0x80;
  unsigned char mask = selector;
  unsigned int first_zero = 8;
  for (unsigned int i = 0; i < 8; ++i) {
    mask |= selector;
    if (!(head & selector)) {
      first_zero = i;
      break;
    }
    selector >>= 1;
  }
  if (first_zero == 1 || first_zero >= 5) return Drop;
  for (unsigned int i = 2; i <= first_zero; ++i) {
    if (!Eat()) return Uncompleted;
    head = Current();
    if ((head & 0xC0) != 0x80) return Drop;
  }
  return Character;
}

InputParser::Output InputParser::ParseESC() {
  if (!Eat()) return Uncompleted;
  switch (Current()) {
    case 'P': return ParseDCS();
    case '[': return ParseCSI();
    case ']': return ParseOSC();
    case ' ':
    case '#':
    case '%':
    case '(':
    case ')':
    case '*':
    case '+':
    case 'O':
    case 'N': {
      if (!Eat()) return Uncompleted;
      return Special;
    }
    default: return Special;
  }
}

InputParser::Output InputParser::ParseDCS() {
  while (true) {
    if (!Eat()) return Uncompleted;
    if (Current() != 0x1b) continue;
    if (!Eat()) return Uncompleted;
    if (Current() != '\\') continue;
    if (pending_.size() == 10 && pending_[2] == '1' && pending_[3] == '$' && pending_[4] == 'r' &&
        pending_[6] == ' ' && pending_[7] == 'q') {
      Output output(CursorShapeT);
      output.cursor_shape = pending_[5] - '0';
      return output;
    }
    return Special;
  }
}

InputParser::Output InputParser::ParseOSC() {
  while (true) {
    if (!Eat()) return Uncompleted;
    if (Current() != 0x1b) continue;
    if (!Eat()) return Uncompleted;
    if (Current() != '\\') continue;
    return Special;
  }
}

InputParser::Output InputParser::ParseCSI() {
  bool altered = false;
  int argument = 0;
  std::vector<int> arguments;
  while (true) {
    if (!Eat()) return Uncompleted;
    if (Current() == '<') {
      altered = true;
      continue;
    }
    if (Current() >= '0' && Current() <= '9') {
      argument *= 10;
      argument += Current() - '0';
      continue;
    }
    if (Current() == ';') {
      arguments.push_back(argument);
      argument = 0;
      continue;
    }
    if (Current() >= '@' && Current() <= '~' && Current() != '<' && Current() != '[') {
      arguments.push_back(argument);
      argument = 0;
      switch (Current()) {
        case 'M': return ParseMouse(altered, true, std::move(arguments));
        case 'm': return ParseMouse(altered, false, std::move(arguments));
        case 'R': return ParseCursorPosition(std::move(arguments));
        default: return Special;
      }
    }
    if (Current() == 0x1b) return Special;
  }
}

InputParser::Output InputParser::ParseMouse(bool /*altered*/, bool pressed, std::vector<int> arguments) {
  if (arguments.size() != 3) return Special;
  Output output(MouseT);
  output.mouse.button = static_cast<Mouse::Button>((arguments[0] & 3) + ((arguments[0] & 64) >> 4));
  if (arguments[0] & 32) {
    output.mouse.motion = Mouse::Moved;
  } else {
    output.mouse.motion = pressed ? Mouse::Pressed : Mouse::Released;
  }
  output.mouse.shift = (arguments[0] & 4) != 0;
  output.mouse.meta = (arguments[0] & 8) != 0;
  output.mouse.control = (arguments[0] & 16) != 0;
  output.mouse.x = arguments[1];
  output.mouse.y = arguments[2];
  return output;
}

InputParser::Output InputParser::ParseCursorPosition(std::vector<int> arguments) {
  if (arguments.size() != 2) return Special;
  Output output(CursorPositionT);
  output.cursor_y = arguments[0];
  output.cursor_x = arguments[1];
  return output;
}

