ScreenInteractive::ScreenInteractive(Dimension dimension, bool alternate_screen)
    : dimension_(dimension), use_alternative_screen_(alternate_screen) {}

ScreenInteractive ScreenInteractive::FitComponent() {
  return ScreenInteractive(Dimension::FitComponent, false);
}

ScreenInteractive ScreenInteractive::Fullscreen() {
  return ScreenInteractive(Dimension::Fullscreen, true);
}

void ScreenInteractive::Flush() { std::cout << '\0' << std::flush; }

void ScreenInteractive::Exit() { exit_requested_ = true; }

void ScreenInteractive::Install() {
  frame_valid_ = false;
  Flush();
  on_exit_functions_.push_back([this] { Flush(); });

  std::cout << "\x1bP$q q\x1b\\";
  on_exit_functions_.push_back([this] {
    std::cout << "\033[?25h";
    std::cout << "\033[" + std::to_string(cursor_reset_shape_) + " q";
  });

  for (const int sig : {SIGTERM, SIGSEGV, SIGINT, SIGILL, SIGABRT, SIGFPE, SIGWINCH, SIGTSTP}) {
    auto old = std::signal(sig, RecordSignal);
    on_exit_functions_.push_back([=] { std::signal(sig, old); });
  }

  struct termios terminal {};
  tcgetattr(STDIN_FILENO, &terminal);
  on_exit_functions_.push_back([=] { tcsetattr(STDIN_FILENO, TCSANOW, &terminal); });

  struct termios raw = terminal;
  raw.c_iflag &= ~static_cast<tcflag_t>(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
  raw.c_lflag &= ~static_cast<tcflag_t>(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
  raw.c_cflag |= CS8;
  raw.c_cc[VMIN] = 0;
  raw.c_cc[VTIME] = 0;
  tcsetattr(STDIN_FILENO, TCSANOW, &raw);

  if (use_alternative_screen_) {
    std::cout << "\x1b[?1049h";
    on_exit_functions_.push_back([] { std::cout << "\x1b[?1049l"; });
  }
  std::cout << "\x1b[?7l";
  on_exit_functions_.push_back([] { std::cout << "\x1b[?7h"; });
  for (const int mode : {1000, 1003, 1015, 1006}) {
    std::cout << "\x1b[?" + std::to_string(mode) + "h";
    on_exit_functions_.push_back([=] { std::cout << "\x1b[?" + std::to_string(mode) + "l"; });
  }
  Flush();
  quit_ = false;
}

void ScreenInteractive::Uninstall() {
  while (!on_exit_functions_.empty()) {
    on_exit_functions_.back()();
    on_exit_functions_.pop_back();
  }
}

void ScreenInteractive::HandleEvent(ComponentBase* component, Event event) {
  if (event.is_cursor_position()) {
    cursor_x_ = event.cursor_x;
    cursor_y_ = event.cursor_y;
    return;
  }
  if (event.is_cursor_shape()) {
    cursor_reset_shape_ = event.cursor_shape;
    return;
  }
  if (event.is_mouse()) {
    event.mouse().x -= cursor_x_;
    event.mouse().y -= cursor_y_;
  }
  const bool handled = component->OnEvent(event);
  frame_valid_ = false;
  if (!handled && event == Event::CtrlC()) RecordSignal(SIGABRT);
}

void ScreenInteractive::Suspend() {
  std::cout << reset_cursor_position_;
  reset_cursor_position_.clear();
  Screen screen(dimx_, dimy_);
  std::cout << screen.ResetPosition(true);
  Uninstall();
  dimx_ = 0;
  dimy_ = 0;
  Flush();
  std::raise(SIGTSTP);
  Install();
}

void ScreenInteractive::ExecuteSignalHandlers() {
  int exit_count = g_signal_exit_count.exchange(0);
  while (exit_count--) Exit();
  int stop_count = g_signal_stop_count.exchange(0);
  while (stop_count--) Suspend();
  int resize_count = g_signal_resize_count.exchange(0);
  while (resize_count--) pending_resize_++;
}

void ScreenInteractive::Draw(ComponentBase* component) {
  if (frame_valid_) return;
  Element document = component->Render();
  int dimx = 0;
  int dimy = 0;
  const Dimensions terminal = TerminalSize();
  document->ComputeRequirement();
  switch (dimension_) {
    case Dimension::Fullscreen:
      dimx = terminal.dimx;
      dimy = terminal.dimy;
      break;
    case Dimension::FitComponent:
      dimx = std::min(document->requirement().min_x, terminal.dimx);
      dimy = std::min(document->requirement().min_y, terminal.dimy);
      break;
  }

  const bool resized = (dimx != dimx_) || (dimy != dimy_);
  std::cout << reset_cursor_position_;
  reset_cursor_position_.clear();
  {
    Screen old(std::max(dimx_, 0), std::max(dimy_, 0));
    std::cout << old.ResetPosition(resized);
  }
  if ((dimx < dimx_) && !use_alternative_screen_) {
    std::cout << "\033[J";
    std::cout << "\033[H";
  }
  if (resized) {
    dimx_ = dimx;
    dimy_ = dimy;
  }
  ++frame_counter_;
  if (!use_alternative_screen_ && (previous_frame_resized_ || frame_counter_ % 40 == 0)) {
    std::cout << "\033[6n";
  }
  previous_frame_resized_ = resized;

  Screen screen(dimx_, dimy_);
  Render(screen, document.get());

  {
    const Screen::Cursor cursor = screen.cursor();
    const int dx = dimx_ - 1 - cursor.x + static_cast<int>(dimx_ != terminal.dimx);
    const int dy = dimy_ - 1 - cursor.y;
    set_cursor_position_.clear();
    reset_cursor_position_.clear();
    if (dy != 0) {
      set_cursor_position_ += "\x1b[" + std::to_string(dy) + "A";
      reset_cursor_position_ += "\x1b[" + std::to_string(dy) + "B";
    }
    if (dx != 0) {
      set_cursor_position_ += "\x1b[" + std::to_string(dx) + "D";
      reset_cursor_position_ += "\x1b[" + std::to_string(dx) + "C";
    }
    if (cursor.shape == Screen::Cursor::Hidden) {
      set_cursor_position_ += "\033[?25l";
    } else {
      set_cursor_position_ += "\033[?25h";
      set_cursor_position_ += "\033[" + std::to_string(static_cast<int>(cursor.shape)) + " q";
    }
  }

  std::cout << screen.ToString() << set_cursor_position_;
  Flush();
  frame_valid_ = true;
}

void ScreenInteractive::Loop(Component component) {
  g_active_screen = this;
  Install();

  std::vector<Event> events;
  InputParser parser([&](Event e) { events.push_back(std::move(e)); });

  while (!quit_) {
    ExecuteSignalHandlers();

    // Wait for input (or a short timeout to let pending escape sequences expire).
    fd_set fds;
    FD_ZERO(&fds);
    FD_SET(STDIN_FILENO, &fds);
    timeval tv{};
    tv.tv_sec = 0;
    tv.tv_usec = 20000;
    const int ready = select(STDIN_FILENO + 1, &fds, nullptr, nullptr, &tv);
    if (ready > 0) {
      char buffer[100];
      const ssize_t n = read(STDIN_FILENO, buffer, sizeof(buffer));
      if (n > 0) {
        for (ssize_t i = 0; i < n; ++i) parser.Add(buffer[i]);
      } else if (n == 0) {
        // End of input: nothing more will ever arrive from the keyboard.
        stdin_closed_ = true;
      }
    } else {
      parser.Timeout(20);
    }
    if (stdin_closed_) {
      // Avoid spinning; wait for signals instead.
      usleep(20000);
    }

    ExecuteSignalHandlers();
    if (pending_resize_ > 0) {
      pending_resize_ = 0;
      events.push_back(Event::Custom());
    }
    for (size_t i = 0; i < events.size(); ++i) {
      HandleEvent(component.get(), events[i]);
      ExecuteSignalHandlers();
    }
    events.clear();
    if (exit_requested_) quit_ = true;
    Draw(component.get());
  }

  std::cout << reset_cursor_position_;
  g_active_screen = nullptr;
  Uninstall();
  std::cout << '\r';
  if (!use_alternative_screen_) std::cout << std::endl;
  std::cout << std::flush;
}

