#include <cstdio>
#include <cstring>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

#include "dom.h"
#include "json.h"
#include "jsontui.h"
#include "terminal.h"

namespace {

const char* kHelp =
    "  json-tui {OPTIONS} [file]\n"
    "\n"
    "    A JSON terminal UI\n"
    "\n"
    "  OPTIONS:\n"
    "\n"
    "      file                              A JSON file. Omit to read from stdin.\n"
    "      -h, --help                        Display this help menu.\n"
    "      -v, --version                     Print version.\n"
    "      -k, --key, --keybinding           Display key binding.\n"
    "      -f, --fullscreen                  Display the JSON in fullscreen, in an\n"
    "                                        alternate buffer\n"
    "      \"--\" can be used to terminate flag options and force all following\n"
    "      arguments to be treated as positional options\n"
    "\n"
    "    If no file is given, json-tui reads JSON from the standard input\n"
    "    Please report bugs to:https://github.com/ArthurSonzogni/json-tui/issues\n";

struct Options {
  bool help = false;
  bool version = false;
  bool keybinding = false;
  bool fullscreen = false;
  std::vector<std::string> positional;
};

// Returns false on invalid arguments.
bool ParseArguments(int argc, char** argv, Options& options) {
  bool only_positional = false;
  for (int i = 1; i < argc; ++i) {
    const std::string arg = argv[i];
    if (only_positional || arg.empty() || arg[0] != '-' || arg == "-") {
      options.positional.push_back(arg);
      continue;
    }
    if (arg == "--") {
      only_positional = true;
      continue;
    }
    if (arg.size() > 1 && arg[1] == '-') {
      if (arg == "--help") {
        options.help = true;
      } else if (arg == "--version") {
        options.version = true;
      } else if (arg == "--key" || arg == "--keybinding") {
        options.keybinding = true;
      } else if (arg == "--fullscreen") {
        options.fullscreen = true;
      } else {
        return false;
      }
      continue;
    }
    // Group of short flags.
    for (size_t j = 1; j < arg.size(); ++j) {
      switch (arg[j]) {
        case 'h': options.help = true; break;
        case 'v': options.version = true; break;
        case 'k': options.keybinding = true; break;
        case 'f': options.fullscreen = true; break;
        default: return false;
      }
    }
  }
  return options.positional.size() <= 1;
}

}  // namespace

int main(int argc, char** argv) {
  Options options;
  if (!ParseArguments(argc, argv, options)) {
    std::cerr << "Invalid arguments" << std::endl;
    return 1;
  }
  if (options.help) {
    std::cout << kHelp;
    return 0;
  }
  if (options.version) {
    std::cout << "1.4.1" << std::endl;
    return 0;
  }
  if (options.keybinding) {
    jt::Element document = jt::KeyBindingElement();
    document->ComputeRequirement();
    jt::Screen screen(document->requirement().min_x, document->requirement().min_y);
    jt::Render(screen, document.get());
    std::cout << screen.ToString() << '\0' << std::endl;
    return 0;
  }

  std::string input;
  bool from_stdin = options.positional.empty();
  if (from_stdin) {
    std::cout << "Reading from stdin..." << std::flush;
    std::stringstream ss;
    ss << std::cin.rdbuf();
    input = ss.str();
  } else {
    std::ifstream file(options.positional[0], std::ios::binary);
    if (!file) {
      std::cerr << "Could not open file " << options.positional[0] << std::endl;
      return 1;
    }
    std::stringstream ss;
    ss << file.rdbuf();
    input = ss.str();
  }

  jt::JsonPtr json;
  try {
    json = jt::ParseJson(input);
  } catch (const jt::JsonError& e) {
    std::cerr << std::endl << e.what() << std::endl;
    return 1;
  }

  if (from_stdin) {
    // The keyboard is needed for the interactive part.
    if (!std::freopen("/dev/tty", "r", stdin)) {
      // Keep going with whatever stdin is.
    }
  }

  jt::ScreenInteractive screen =
      options.fullscreen ? jt::ScreenInteractive::Fullscreen() : jt::ScreenInteractive::FitComponent();
  jt::Component viewer = jt::MakeJsonViewer(*json, &screen);
  screen.Loop(viewer);
  return 0;
}
