cat > /workspace/src/jsontui.cpp <<'EOF'
#include "jsontui.h"

#include <algorithm>
#include <climits>
#include <sstream>

namespace jt {

namespace {

// Appearance helpers --------------------------------------------------------

Color ValueColor(const JsonValue& v) {
  switch (v.type) {
    case JsonType::String: return Color::GreenLight();
    case JsonType::Boolean: return Color::YellowLight();
    case JsonType::Null: return Color::RedLight();
    default: return Color::CyanLight();
  }
}

std::string ValueText(const JsonValue& v) {
  switch (v.type) {
    case JsonType::String: return "\"" + v.string + "\"";
    case JsonType::Boolean: return v.boolean ? "true" : "false";
    case JsonType::Null: return "null";
    default: return DumpNumber(v);
  }
}

// Multi-line text: every line is a wrapping paragraph.
Element MultilineParagraph(const std::string& s) {
  Elements lines;
  std::string line;
  std::stringstream ss(s);
  while (std::getline(ss, line, '\n')) lines.push_back(paragraph(line));
  return vbox(std::move(lines));
}

Element FocusManagement(Element e, bool focused, bool active) {
  if (focused) return focus(std::move(e));
  if (active) return select(std::move(e));
  return e;
}

// Context describing where a node sits in the tree.
struct Context {
  std::string indent;  // leading spaces of the node's own lines
  bool has_key = false;
  std::string key;
  bool is_last = true;  // no trailing comma
  int depth = 0;
  bool bare = false;  // table cell: no prefix/suffix, element fills the cell
};

// Base class of every node in the JSON tree.
class JsonNode : public ComponentBase {
 public:
  virtual bool IsCollapsible() const { return false; }
  virtual int MinDepth() { return 0; }
  virtual int MaxDepth() { return 0; }
  virtual void ExpandLevel(int) {}
  virtual void CollapseLevel(int) {}
};

using JsonNodePtr = std::shared_ptr<JsonNode>;
JsonNodePtr MakeNode(const JsonValue& value, Context ctx);

Elements Prefix(const Context& ctx) {
  Elements out;
  out.push_back(text(ctx.indent));
  if (ctx.has_key) {
    out.push_back(color(Color::BlueLight(), text("\"" + ctx.key + "\"")));
    out.push_back(text(": "));
  }
  return out;
}

// A clickable toggle (used for `{`/`[` headers and the table view switch).
class Toggle : public ComponentBase {
 public:
  Toggle(std::function<Element(bool highlighted)> render, std::function<void()> on_toggle)
      : render_(std::move(render)), on_toggle_(std::move(on_toggle)) {}

  Element Render() override {
    const bool is_focused = Focused();
    const bool is_active = Active();
    Element e = render_(is_focused || hovered_);
    e = FocusManagement(std::move(e), is_focused, is_active);
    return reflect(box_, std::move(e));
  }

  bool Focusable() const override { return true; }

  bool OnEvent(Event event) override {
    if (event.is_mouse()) return OnMouseEvent(event);
    hovered_ = false;
    if (event == Event::Character(' ') || event == Event::Return()) {
      on_toggle_();
      return true;
    }
    return false;
  }

 private:
  bool OnMouseEvent(const Event& event) {
    hovered_ = box_.Contain(event.mouse().x, event.mouse().y);
    if (!hovered_) return false;
    if (event.mouse().button == Mouse::Left && event.mouse().motion == Mouse::Pressed) {
      on_toggle_();
      return true;
    }
    return false;
  }

  std::function<Element(bool)> render_;
  std::function<void()> on_toggle_;
  bool hovered_ = false;
  Box box_;
};

// Scalar values ---------------------------------------------------------------
class LeafNode : public JsonNode {
 public:
  LeafNode(const JsonValue& value, Context ctx) : value_(value), ctx_(std::move(ctx)) {}

  Element Render() override {
    const bool is_focused = Focused();
    const bool is_active = Active();
    Element e = MultilineParagraph(ValueText(value_));
    e = color(ValueColor(value_), std::move(e));
    if (is_focused) e = inverted(std::move(e));
    e = FocusManagement(std::move(e), is_focused, is_active);
    e = reflect(box_, std::move(e));
    if (ctx_.bare) return e;
    Elements line = Prefix(ctx_);
    line.push_back(std::move(e));
    line.push_back(text(ctx_.is_last ? "" : ","));
    return hbox(std::move(line));
  }

  bool Focusable() const override { return true; }

  bool OnEvent(Event event) override {
    if (event.is_mouse() && box_.Contain(event.mouse().x, event.mouse().y)) TakeFocus();
    return false;
  }

 private:
  const JsonValue& value_;
  Context ctx_;
  Box box_;
};

// Objects and arrays -----------------------------------------------------------
bool IsTableable(const JsonValue& v) {
  if (!v.IsArray() || v.array.size() < 2) return false;
  for (const auto& e : v.array)
    if (!e->IsObject()) return false;
  return true;
}

bool DefaultExpanded(const JsonValue& v, int depth) {
  if (v.IsObject()) return depth <= 1;
  return depth <= 0;
}

class ContainerNode : public JsonNode {
 public:
  ContainerNode(const JsonValue& value, Context ctx)
      : value_(value), ctx_(std::move(ctx)), tableable_(IsTableable(value)) {
    if (tableable_) {
      table_toggle_ = std::make_shared<Toggle>(
          [this](bool highlighted) {
            Element e = text(table_mode_ ? "(array view)" : "(table view)");
            e = color(Color::GrayDark(), std::move(e));
            if (highlighted) e = inverted(std::move(e));
            return e;
          },
          [this] { ToggleTableMode(); });
    }
    Build();
  }

  bool IsCollapsible() const override { return !table_mode_; }

  int MinDepth() override {
    if (!expanded_) return 0;
    int m = INT_MAX;
    for (auto& child : nodes_) {
      if (child->IsCollapsible()) m = std::min(m, child->MinDepth());
    }
    return m == INT_MAX ? 1 : 1 + m;
  }

  int MaxDepth() override {
    if (!expanded_) return 0;
    int m = 0;
    for (auto& child : nodes_) {
      if (child->IsCollapsible()) m = std::max(m, child->MaxDepth());
    }
    return 1 + m;
  }

  void ExpandLevel(int level) override {
    if (level < 0) return;
    expanded_ = true;
    for (auto& child : nodes_) {
      if (child->IsCollapsible()) child->ExpandLevel(level - 1);
    }
  }

  void CollapseLevel(int level) override {
    if (level <= 0) expanded_ = false;
    for (auto& child : nodes_) {
      if (child->IsCollapsible()) child->CollapseLevel(level - 1);
    }
  }

  Element Render() override {
    Elements rows;
    if (table_mode_) {
      Elements header = Prefix(ctx_);
      header.push_back(table_toggle_->Render());
      rows.push_back(hbox(std::move(header)));
      rows.push_back(RenderTable());
      return reflect(box_, vbox(std::move(rows)));
    }

    Elements header = Prefix(ctx_);
    header.push_back(header_toggle_->Render());
    if (tableable_) {
      header.push_back(text("   "));
      header.push_back(table_toggle_->Render());
    }
    rows.push_back(hbox(std::move(header)));
    if (expanded_) {
      for (auto& child : nodes_) rows.push_back(child->Render());
      rows.push_back(text(ctx_.indent + CloseChar() + (ctx_.is_last ? "" : ",")));
    }
    return reflect(box_, vbox(std::move(rows)));
  }

  bool OnEvent(Event event) override {
    if (event.is_mouse()) return OnMouseEvent(event);
    if (!Focused()) return false;
    if (ActiveChild() && ActiveChild()->OnEvent(event)) return true;
    if (VerticalEvent(event)) return true;
    if (table_mode_) return false;
    if (event == Event::Character('+')) {
      if (!expanded_) {
        expanded_ = true;
      } else {
        ExpandLevel(MinDepth());
      }
      return true;
    }
    if (event == Event::Character('-')) {
      if (!expanded_) return false;
      CollapseLevel(MaxDepth() - 1);
      return true;
    }
    return false;
  }

  ComponentBase* ActiveChild() override {
    if (children_.empty()) return nullptr;
    return children_[static_cast<size_t>(selector_) % children_.size()].get();
  }

  void SetActiveChild(ComponentBase* child) override {
    for (size_t i = 0; i < children_.size(); ++i) {
      if (children_[i].get() == child) {
        selector_ = static_cast<int>(i);
        return;
      }
    }
  }

 private:
  std::string OpenChar() const { return value_.IsObject() ? "{" : "["; }
  std::string CloseChar() const { return value_.IsObject() ? "}" : "]"; }

  Context ChildContext() const {
    Context c;
    c.indent = ctx_.indent + "  ";
    c.depth = ctx_.depth + 1;
    return c;
  }

  // (Re)create every child component with default state.
  void Build() {
    DetachAllChildren();
    nodes_.clear();
    cells_.clear();
    selector_ = 0;
    expanded_ = DefaultExpanded(value_, ctx_.depth);

    header_toggle_ = std::make_shared<Toggle>(
        [this](bool highlighted) {
          std::string label = OpenChar();
          if (!expanded_) label += "..." + CloseChar() + (ctx_.is_last ? "" : ",");
          Element e = text(label);
          return highlighted ? inverted(std::move(e)) : bold(std::move(e));
        },
        [this] { expanded_ = !expanded_; });

    if (table_mode_) {
      BuildTable();
      Add(table_toggle_);
      Add(rows_);
      return;
    }

    const Context child_ctx = ChildContext();
    Components children;
    if (value_.IsObject()) {
      for (size_t i = 0; i < value_.object.size(); ++i) {
        Context c = child_ctx;
        c.has_key = true;
        c.key = value_.object[i].first;
        c.is_last = (i + 1 == value_.object.size());
        auto node = MakeNode(*value_.object[i].second, c);
        nodes_.push_back(node);
        children.push_back(node);
      }
    } else {
      for (size_t i = 0; i < value_.array.size(); ++i) {
        Context c = child_ctx;
        c.is_last = (i + 1 == value_.array.size());
        auto node = MakeNode(*value_.array[i], c);
        nodes_.push_back(node);
        children.push_back(node);
      }
    }
    children_container_ = Container::Vertical(std::move(children));
    maybe_children_ = Maybe(children_container_, &expanded_);

    if (tableable_) {
      Add(Container::Horizontal({header_toggle_, table_toggle_}));
    } else {
      Add(header_toggle_);
    }
    Add(maybe_children_);
  }

  void ToggleTableMode() {
    table_mode_ = !table_mode_;
    Build();
    table_toggle_->TakeFocus();
  }

  // Table view ------------------------------------------------------------
  void BuildTable() {
    // Columns: keys in order of first appearance.
    columns_.clear();
    for (const auto& row : value_.array) {
      for (const auto& kv : row->object) {
        if (std::find(columns_.begin(), columns_.end(), kv.first) == columns_.end()) {
          columns_.push_back(kv.first);
        }
      }
    }
    const Context cell_ctx = [&] {
      Context c;
      c.depth = ctx_.depth + 1;
      c.bare = true;
      return c;
    }();
    Components row_components;
    for (const auto& row : value_.array) {
      std::vector<JsonNodePtr> cells;
      Components focusable;
      for (const auto& column : columns_) {
        const JsonValue* v = row->Find(column);
        if (v == nullptr) {
          cells.push_back(nullptr);
          continue;
        }
        auto node = MakeNode(*v, cell_ctx);
        cells.push_back(node);
        focusable.push_back(node);
      }
      cells_.push_back(std::move(cells));
      row_components.push_back(Container::Horizontal(std::move(focusable)));
    }
    rows_ = Container::Vertical(std::move(row_components));
  }

  Element RenderTable() {
    // Grid coordinates: even columns/rows hold borders, odd ones hold cells.
    const int ncols = static_cast<int>(columns_.size());
    const int nrows = static_cast<int>(value_.array.size());
    const int xsize = 2 * (ncols + 1) + 1;  // index column + data columns
    const int ysize = 2 * (nrows + 1) + 1;  // header row + data rows
    std::vector<Elements> grid(static_cast<size_t>(ysize));
    for (auto& line : grid) line.assign(static_cast<size_t>(xsize), nullptr);

    auto sep = [](const char* c) { return flex(separatorCharacter(c)); };
    auto corner = [](const char* c) { return notflex(separatorCharacter(c)); };
    auto cell = [](Element e) { return flex_shrink(std::move(e)); };

    // The bordered area covers the data columns (or the index column when
    // there are no data columns at all).
    const int border_left = ncols == 0 ? 0 : 2;  // grid x of the left border
    const int border_right = xsize - 1;

    // Header row.
    grid[1][1] = cell(color(Color::GrayDark(), text("")));
    for (int c = 0; c < ncols; ++c) grid[1][static_cast<size_t>(3 + 2 * c)] = cell(text(columns_[static_cast<size_t>(c)]));
    // Data rows.
    for (int r = 0; r < nrows; ++r) {
      const size_t gy = static_cast<size_t>(3 + 2 * r);
      grid[gy][1] = cell(color(Color::GrayDark(), text(std::to_string(r))));
      for (int c = 0; c < ncols; ++c) {
        auto& node = cells_[static_cast<size_t>(r)][static_cast<size_t>(c)];
        grid[gy][static_cast<size_t>(3 + 2 * c)] = cell(node ? node->Render() : emptyElement());
      }
    }
    // Borders. Heavy around the header, light elsewhere; junctions are the
    // merged box drawing characters.
    for (int x = border_left; x <= border_right; ++x) {
      const bool is_sep_col = (x % 2 == 0);
      const bool left = (x == border_left);
      const bool right = (x == border_right);
      // top border (y = 0)
      grid[0][static_cast<size_t>(x)] = is_sep_col ? corner(left ? "┏" : right ? "┓" : "┳") : sep("━");
      // header row separators (y = 1)
      if (is_sep_col) grid[1][static_cast<size_t>(x)] = sep("┃");
      // header bottom (y = 2)
      grid[2][static_cast<size_t>(x)] = is_sep_col ? corner(left ? "┡" : right ? "┩" : "╇") : sep("━");
      // data rows
      for (int r = 0; r < nrows; ++r) {
        if (is_sep_col) grid[static_cast<size_t>(3 + 2 * r)][static_cast<size_t>(x)] = sep("│");
      }
      // bottom border
      grid[static_cast<size_t>(ysize - 1)][static_cast<size_t>(x)] =
          is_sep_col ? corner(left ? "└" : right ? "┘" : "┴") : sep("─");
    }
    for (auto& line : grid)
      for (auto& e : line)
        if (!e) e = emptyElement();
    return gridbox(std::move(grid));
  }

  // Vertical container behaviour over children_.
  bool OnMouseEvent(Event event) {
    for (auto& child : children_) {
      if (child->OnEvent(event)) return true;
    }
    return false;
  }

  void MoveSelector(int dir) {
    for (int i = selector_ + dir; i >= 0 && i < static_cast<int>(children_.size()); i += dir) {
      if (children_[static_cast<size_t>(i)]->Focusable()) {
        selector_ = i;
        return;
      }
    }
  }

  void MoveSelectorWrap(int dir) {
    if (children_.empty()) return;
    const int n = static_cast<int>(children_.size());
    for (int offset = 1; offset < n; ++offset) {
      const int i = ((selector_ + offset * dir) % n + n) % n;
      if (children_[static_cast<size_t>(i)]->Focusable()) {
        selector_ = i;
        return;
      }
    }
  }

  bool VerticalEvent(Event event) {
    const int old_selected = selector_;
    if (event == Event::ArrowUp() || event == Event::Character('k')) MoveSelector(-1);
    if (event == Event::ArrowDown() || event == Event::Character('j')) MoveSelector(+1);
    if (event == Event::PageUp()) {
      for (int i = 0; i < box_.y_max - box_.y_min; ++i) MoveSelector(-1);
    }
    if (event == Event::PageDown()) {
      for (int i = 0; i < box_.y_max - box_.y_min; ++i) MoveSelector(1);
    }
    if (event == Event::Home()) {
      for (size_t i = 0; i < children_.size(); ++i) MoveSelector(-1);
    }
    if (event == Event::End()) {
      for (size_t i = 0; i < children_.size(); ++i) MoveSelector(+1);
    }
    if (event == Event::Tab()) MoveSelectorWrap(+1);
    if (event == Event::TabReverse()) MoveSelectorWrap(-1);
    selector_ = std::max(0, std::min(static_cast<int>(children_.size()) - 1, selector_));
    return old_selected != selector_;
  }

  const JsonValue& value_;
  Context ctx_;
  bool tableable_;
  bool table_mode_ = false;
  bool expanded_ = true;
  int selector_ = 0;
  Box box_;

  std::shared_ptr<Toggle> header_toggle_;
  std::shared_ptr<Toggle> table_toggle_;
  std::vector<JsonNodePtr> nodes_;
  Component children_container_;
  Component maybe_children_;

  std::vector<std::string> columns_;
  std::vector<std::vector<JsonNodePtr>> cells_;
  Component rows_;
};

JsonNodePtr MakeNode(const JsonValue& value, Context ctx) {
  if (value.IsContainer()) return std::make_shared<ContainerNode>(value, std::move(ctx));
  return std::make_shared<LeafNode>(value, std::move(ctx));
}

// Top level component ----------------------------------------------------------
class Viewer : public ComponentBase {
 public:
  Viewer(const JsonValue& root, ScreenInteractive* screen) : screen_(screen) {
    Context ctx;
    root_ = MakeNode(root, ctx);
    Add(root_);
  }

  Element Render() override { return yframe(root_->Render()); }

  bool OnEvent(Event event) override {
    if (event == Event::Character('q') || event == Event::Escape()) {
      screen_->Exit();
      return true;
    }
    if (event.is_mouse()) {
      if (event.mouse().button == Mouse::WheelUp) return root_->OnEvent(Event::ArrowUp());
      if (event.mouse().button == Mouse::WheelDown) return root_->OnEvent(Event::ArrowDown());
    }
    if (event == Event::Character('g')) {
      if (g_pending_) {
        g_pending_ = false;
        while (root_->OnEvent(Event::ArrowDown())) {
        }
        return true;
      }
      g_pending_ = true;
      return true;
    }
    g_pending_ = false;
    if (event == Event::Character('G')) {
      while (root_->OnEvent(Event::ArrowUp())) {
      }
      return true;
    }
    return root_->OnEvent(event);
  }

 private:
  JsonNodePtr root_;
  ScreenInteractive* screen_;
  bool g_pending_ = false;
};

}  // namespace

Component MakeJsonViewer(const JsonValue& root, ScreenInteractive* screen) {
  return std::make_shared<Viewer>(root, screen);
}

Element KeyBindingElement() {
  // Rendered as a fixed table with light borders and a cyan header.
  struct Row {
    std::vector<std::string> keys;
    std::vector<std::string> actions;
  };
  const std::vector<Row> rows = {
      {{"Navigate"}, {"← ↑ ↓ →", "h j k l", "Mouse::WheelUp", "Mouse::WheelDown"}},
      {{"Toggle"}, {"enter", "Mouse::Left"}},
      {{"Deep", " - Expand", " - Collapse"}, {"", "+", "-"}},
      {{"Exit"}, {"Escape", "q"}},
      {{"Navigate", " - first", " - last", " - top", " - bottom"},
       {"", "page-up", "page-down", "gg", "G"}},
  };
  const int w1 = 11;
  const int w2 = 16;
  auto pad = [](const std::string& s, int w) {
    std::string out = s;
    int width = string_width(s);
    while (width < w) {
      out += " ";
      ++width;
    }
    return out;
  };
  auto hline = [&](const char* l, const char* m, const char* r) {
    std::string out = l;
    for (int i = 0; i < w1; ++i) out += "─";
    out += m;
    for (int i = 0; i < w2; ++i) out += "─";
    out += r;
    return text(out);
  };
  Elements lines;
  lines.push_back(hline("┌", "┬", "┐"));
  lines.push_back(hbox({text("│"), color(Color::Cyan(), text(pad("keys", w1))), text("│"),
                        color(Color::Cyan(), text(pad("action", w2))), text("│")}));
  for (const auto& row : rows) {
    lines.push_back(hline("├", "┼", "┤"));
    const size_t n = std::max(row.keys.size(), row.actions.size());
    for (size_t i = 0; i < n; ++i) {
      const std::string k = i < row.keys.size() ? row.keys[i] : "";
      const std::string a = i < row.actions.size() ? row.actions[i] : "";
      lines.push_back(text("│" + pad(k, w1) + "│" + pad(a, w2) + "│"));
    }
  }
  lines.push_back(hline("└", "┴", "┘"));
  return vbox(std::move(lines));
}

}  // namespace jt
